INSERT INTO `komik` (`id`, `judul`, `slug`, `penulis`, `penerbit`, `gambar`, `tahun_terbit`) VALUES
(1, 'Manhua Hero? I Quit A Long Time Ago (END)', 'manhua-hero-i-quit-a-long-time-ago-end', 'Lima tahun sebelum cerita dimulai, dunia diselamatkan oleh pahlawan super terkuat yang dikenal dengan nama Zero. Keberadaannya menginspirasi munculnya para pahlawan lain, sehingga Zero dianggap sebagai pahlawan legendaris. Namun, setelah lima tahun berperang tanpa henti, Zero memutuskan untuk pensiun dan menjalani kehidupan biasa.  Zero, yang nama aslinya adalah Lin Jie, kini menjadi seorang pemuda yang malas dan hanya ingin hidup damai bersama adik perempuannya, Lin Wan. Adik perempuannya ini adalah penggemar berat Zero dan terus mendesak Lin Jie untuk mencari pekerjaan. Suatu hari, Lin Jie bertemu dengan pahlawan peringkat E yang bernama Xiao Zhan. Dengan izin Lin Wan, Xiao Zhan merekrut Lin Jie tanpa menyadari identitas aslinya.  Sejak saat itu, Lin Jie kembali terlibat dalam dunia kepahlawanan. Meskipun kekuatannya sangat luar biasa dan tidak tertandingi, ia berusaha keras untuk menyembunyikan identitasnya sebagai Zero dari orang-orang. Namun, dengan semakin banyak ancaman yang muncul, termasuk monster dan penjahat yang bersekutu dengan kekuatan gelap, Lin Jie harus berulang kali menggunakan kekuatannya. Akibatnya, ia kembali menarik perhatian Asosiasi Pahlawan dan para penjahat.  Petualangan Lin Jie dan rekan-rekannya di Asosiasi Pahlawan menghadirkan banyak aksi dan komedi. Ia sering kali kesal dengan gangguan yang terus-menerus menguji keinginannya untuk hidup tenang. Meskipun ia bersikeras telah pensiun, ia tetap menjadi harapan terakhir umat manusia untuk melawan kejahatan yang semakin besar.', '', 'https://kenmei.b-cdn.net/covers/manga_series/2002/cover/jpeg-thumbnail-large-c01599905ae8cd2f3619fedc0d87ba65.jpeg', NULL),
(2, 'Manga Horimiya (END)', 'manga-horimiya-end', 'Sinopsis Horimiya menceritakan tentang Kyoko Hori, siswi populer yang cerdas, dan Izumi Miyamura, siswa pendiam yang tampak suram dan seperti kutu buku. Setelah keduanya bertemu secara tidak sengaja di luar sekolah, mereka menemukan rahasia masing-masing dan sepakat untuk merahasiakannya. Hori adalah ibu rumah tangga yang mengurus adiknya di rumah, sementara Miyamura memiliki tato dan tindikan yang tersembunyi di balik penampilannya. Seiring berjalannya waktu, keduanya menjadi teman dekat, mulai saling membuka diri, dan mengembangkan perasaan romantis satu sama lain.', '', 'https://i.redd.it/n7lvkmtvjv571.jpg', NULL),
(3, 'Manga Attack on Titan (Shingeki no Kyojin) (END)', 'manga-attack-on-titan-shingeki-no-kyojin-end', 'Di dunia yang telah dihancurkan oleh kemunculan para raksasa (Titan), umat manusia terpaksa hidup di dalam kota yang dilindungi oleh tiga lapisan tembok raksasa: Maria, Rose, dan Sina. Titan adalah makhluk humanoid raksasa pemakan manusia yang muncul tiba-tiba sekitar seratus tahun sebelumnya, dan asal-usul mereka misterius.  Kisah berpusat pada Eren Yeager, sahabat masa kecilnya Mikasa Ackerman, dan Armin Arlert, yang hidup tenang di balik tembok. Namun, kedamaian hancur saat Titan Kolosal menjebol Tembok Maria, menyebabkan invasi Titan ke wilayah manusia. Kehilangan ibunya di hadapan Titan membuat Eren bersumpah untuk membasmi semua Titan.  Mereka pun bergabung dengan Survey Corps (Pasukan Pengintai), sebuah divisi militer yang berani keluar dari tembok untuk menghadapi Titan. Seiring perjalanan, mereka menemukan rahasia mengejutkan: Titan bukan hanya musuh, tetapi terkait erat dengan sejarah manusia, tembok, dan kekuatan misterius yang dimiliki Eren.  Cerita berkembang menjadi konflik lebih luas bukan hanya perjuangan melawan Titan, tetapi juga perebutan kebebasan, kebenaran dunia, dan pertarungan ideologi antar-manusia itu sendiri.', '', 'https://fictionhorizon.com/wp-content/uploads/2023/10/Attack-on-titan-season-1-941x1300.webp', NULL),
(4, 'Manga Akame ga Kill (EN Sub) (END)', 'manga-akame-ga-kill-en-sub-end', 'Seorang pemuda desa bernama Tatsumi berangkat ke ibu kota kekaisaran bersama teman-temannya dengan harapan bisa mengubah nasib dan membantu desanya yang miskin. Namun, sesampainya di ibu kota, ia menyadari kenyataan pahit: kekaisaran dipenuhi korupsi, ketidakadilan, dan tirani yang menindas rakyat kecil.  Takdir mempertemukannya dengan Night Raid, sebuah kelompok pembunuh bayaran rahasia yang merupakan bagian dari pasukan revolusi. Night Raid bertujuan menggulingkan pemerintah yang korup demi menciptakan negeri yang lebih adil. Anggotanya memiliki senjata legendaris kuno bernama Teigu (Imperial Arms), yang masing-masing memiliki kekuatan unik dan hanya bisa digunakan oleh pemilik yang kompatibel.  Tatsumi kemudian bergabung dengan Night Raid, berjuang bersama rekan-rekannya, termasuk Akame, seorang pendekar pedang dingin dan mematikan namun berhati lembut. Sepanjang perjalanan, mereka menghadapi pertempuran sengit melawan pasukan kekaisaran, termasuk Esdeath, jenderal sadis yang memimpin pasukan khusus dengan kekuatan luar biasa.  Cerita berkembang menjadi pertarungan penuh pengorbanan, di mana setiap karakter menghadapi dilema moral, kehilangan, serta konsekuensi pahit dari peperangan demi masa depan yang lebih baik.', '', 'https://i.pinimg.com/474x/a5/d5/3b/a5d53b0a4903bf997f4786365daa3282.jpg', NULL),
(5, 'Manga Leviathan (Webtoon Korea) (END)', 'manga-leviathan-webtoon-korea-end', 'Setelah bencana besar, permukaan laut bumi naik drastis hingga menenggelamkan hampir seluruh daratan. Peradaban runtuh, dan manusia yang tersisa kini hidup di kapal, rakit, atau koloni terapung yang rapuh. Namun, lautan baru ini bukan hanya penuh badai dan kelaparan, melainkan juga dihuni oleh monster laut raksasa yang disebut Leviathan.  Cerita mengikuti Bota, seorang anak laki-laki yang kehilangan ayahnya dan harus merawat adiknya, Lita. Mereka berdua berjuang bertahan hidup di dunia penuh bahaya:  Monster Leviathan yang bisa menyerang kapan saja.  Bajak laut dan manusia kejam yang saling memangsa demi sumber daya.  Keterbatasan makanan, air, dan tempat tinggal di samudra tak berujung.  Dalam perjalanannya, Bota bertemu teman dan musuh baru, menemukan rahasia tentang asal-usul Leviathan, serta perlahan membentuk tekad untuk melindungi orang-orang yang ia sayangi.', '', 'https://static.wikia.nocookie.net/leviathanmanhwa/images/b/b1/Leviathan_cover.jpg', NULL),
(6, 'Manga Masamune-kun no Revenge (END)', 'manga-masamune-kun-no-revenge-end', 'Masamune Makabe yang dulunya anak gemuk dan dibully, lalu ia memutuskan untuk membalas dendam pada Adagaki Aki, gadis yang mempermalukannya dulu. Dia mengubah dirinya menjadi siswa yang tampan dan populer, dan berencana membuatnya jatuh cinta sebelum ia menolaknya untuk membalas dendam. Dalam upayanya, Masamune dibantu oleh pelayan Aki, Yoshino Koiwai, yang sepertinya tahu rahasia Masamune.', '', 'https://st.cdjapan.co.jp/pictures/l/02/17/NEOBK-2859009.jpg', NULL),
(7, 'Manga Oshi no Ko (END)', 'manga-oshi-no-ko-end', 'Cerita dimulai dengan Gorou Amemiya, seorang dokter kandungan di pedesaan sekaligus penggemar berat idol populer Ai Hoshino, center dari grup B-Komachi. Gorou sangat mengagumi Ai, yang dikenal punya karisma luar biasa di panggung meski masih muda.  Suatu hari, takdir mempertemukannya dengan Ai ketika ia datang ke rumah sakit tempat Gorou bekerja. Ternyata Ai hamil diam-diam dan hendak melahirkan anak kembar. Namun sebelum persalinan, Gorou tewas akibat sebuah insiden tragis. Anehnya, ia bereinkarnasi sebagai salah satu anak Ai, Aquamarine Hoshino (Aqua). Kembarannya bernama Ruby Hoshino, yang ternyata juga merupakan reinkarnasi dari seorang pasien Gorou yang dulunya penggemar Ai.  Kehidupan baru Aqua dan Ruby penuh dengan cahaya serta bayangan dunia hiburan Jepang:  Ai berjuang mempertahankan karier idol sambil menjadi ibu tunggal.  Ruby bercita-cita mengikuti jejak ibunya sebagai idol.  Aqua justru menyimpan dendam: mencari kebenaran tentang siapa ayah biologisnya, yang diyakininya terlibat dalam tragedi kelam yang menimpa Ai.  Kisah ini bukan sekadar tentang gemerlap idol, melainkan juga drama psikologis, misteri, manipulasi industri hiburan, dan perjalanan gelap seorang anak mencari kebenaran.', '', 'https://i1.sndcdn.com/artworks-NJznsjLFP03O2or2-FyXfUQ-t500x500.jpg', NULL),
(8, 'Manga Death Note (END)', 'manga-death-note-end', 'Berlatar di negara Jepang, anime Death Note mengikuti kisah tokoh utamanya yaitu Light Yagami (Mamoru Miyano), seorang pemuda yang masih duduk di bangku SMA.  Karakter Light ini bisa dikatakan sebagai murid cerdas, pintar, tidak mudah terpengaruh, serta memiliki rasa ingin tahu sangat tinggi.  Suatu hari, pemuda berusia 17 tahun itu dikejutkan dengan sebuah buku misterius yang ia temukan di halaman sekolahnya.  Tidak ada yang tahu bahwa buku misterius itu adalah Death Note dan milik seorang Shinigami atau Dewa Kematian bernama Ryuk (Shidou Nakamura).  Ryuk memang diketahui sengaja menjatuhkan buku tersebut ke dalam kehidupan manusia. Sampai akhirnya buku Death Note ditemukan Light dan ia menjadi pemilik kedua.  Light pun membaca dengan rinci tentang cara-cara yang bisa ia lakukan tentang buku misteri ini.  Konon buku tersebut dapat meramal kematian seseorang. Terlebih jika nama orang yang dimaksud memang ada dalam daftar Death Note.  Dalam sinopsis Death Note dikisahkan, barang siapa yang menuliskan nama serta mengetahui wajah seseorang dan menuliskannya di buku maka orang tersebut akan mati.  Meski awalnya tidak percaya, Light yang memiliki rasa ingin tahu tinggi itu kemudian mencoba eksperimen pertamanya.  Saat sedang menonton berita di televisi, Light melihat seorang penjahat yang menyandera korban. Ia pun menuliskan nama penjahat itu ke dalam Death Note.  Tak butuh waktu lama seorang wartawan tv langsung melaporkan berita terkini bahwa penjahat tersebut tewas. Dari situ Light meyakini buku catatan kematian itu memang nyata dan memiliki kekuatan misterius.  Sementara Light sendiri mempunyai misi supaya kehidupan di dunia aman dan tentram sehingga ia berencana memusnahkan semua penjahat dari muka bumi.  Usai eksperimen pertama berhasil, Light terus melancarkan aksinya lewat buku catatan kematian. Dalam tiga hari dilaporkan ada banyak penjahat-penjahat tewas misterius.  Ryuk kemudian mendatangi Light untuk bertransaksi gaib yang memintanya bertukar nyawa dengan mengurangi sisa usia.  Namun, pemuda 17 tahun itu menolaknya sehingga perjanjian itu tidak terjadi namun ia tetap melanjutkan aksinya memberantas kawanan penjahat.  Seiring banyaknya laporan penjahat serta buronan tewas misterius, posisi Light justru terancam bahkan mulai diusut agen FBI.', '', 'https://d28hgpri8am2if.cloudfront.net/book_images/onix/cvr9781421539645/death-note-black-edition-vol-1-9781421539645_hr.jpg', NULL),
(9, 'Manga Instan Death [Sokushi Cheat ga Saikyou Sugite] (END)', 'manga-instan-death-sokushi-cheat-ga-saikyou-sugite-end', 'Dimana menceritakan Takato Yogiri adalah seorang siswa SMA yang menyukai pemainan dan tidur siang. Selama perjalanan sekolah, Yogiri dan teman-temannya bepergian dengan menggunkan bus dan dipanggil ke dunia lain oleh orang bijak Shion yang tiba-tiba muncul dihadapan mereka. Para siswa, yang diberi kemampuan khusus oleh Shion memutuskan untuk mengambil tangan untuk mengambil tantangan untuk menjadi orang bijak, makhluk berpangkat tinggi di dunia ini. Namun, Yogiri, Chichika Dannoura, dan lainnya tidak diberikan hadiah tersebut, dan salah satu diantara mereka ada yang tertinggal di dalam bus saat naga itu mendekat.', '', 'https://a.storyblok.com/f/178900/960x1343/276c6dbbd4/my-instant-death-ability-is-so-overpowered-no-one-in-this-other-world-stands-a-chance-against-me-key-visual.jpg', NULL),
(10, 'Komik Strip Si Juki (END)', 'komik-strip-si-juki-end', 'Si Juki the Movie berkisah tentang petualangan Si Juki dan kawan-kawan melakukan misi penyelamatan dan humor bergambar. Ceritanya dibuat oleh pembuat komik Si Juki, Faza Ibnu Ubaidillah alias Faza Meonk.', '', 'https://bukune.com/wp-content/uploads/2017/10/Cover-Juki-Cari-Kerja-FC.jpg', NULL),
(11, 'Light Novel Unnamed Memory (END)', 'light-novel-unnamed-memory-end', 'Anime Unnamed Memory bercerita tentang Pangeran Oscar dari Falsas yang memiliki kutukan di mana wanita mana pun yang dinikahinya akan mati. Untuk mematahkan kutukan ini, ia mendaki menara Penyihir Bulan Biru, Tinasha, dan meminta bantuannya. Namun, alih-alih mematahkan kutukan itu, Oscar justru meminta Tinasha untuk menjadi istrinya, dengan keyakinan bahwa kekuatan penyihir itu akan melindunginya dari efek kutukan. Tinasha menolak, tetapi setuju untuk tinggal bersama Oscar di istana Falsas selama setahun untuk meneliti mantra kutukan, sambil menghadapi rahasia gelap masa lalu Tinasha yang mulai terkuak.', '', 'https://cdn.novelupdates.com/images/2020/02/unnamedmemory_v1b.jpg', NULL),
(12, 'Manga Solo Leveling (END)', 'manga-solo-leveling-end', 'Solo Leveling menceritakan kisah Sung Jin-woo, hunter terlemah di dunia yang mendapatkan kemampuan untuk naik level secara mandiri melalui System misterius setelah hampir mati di sebuah dungeon. Berkat kemampuannya, Jin-woo mulai bertarung melawan monster untuk mengumpulkan kekuatan dan mengungkap misteri di balik gerbang dan kebangkitannya, menjadi pahlawan terkuat yang melindungi umat manusia dari ancaman monster.', '', 'https://upload.wikimedia.org/wikipedia/id/thumb/9/99/Solo_Leveling_Webtoon.png/250px-Solo_Leveling_Webtoon.png', NULL),
(13, 'Manga Revenge of the Iron-Blooded Sword Hound (OnGoing)', 'manga-revenge-of-the-iron-blooded-sword-hound-ongoing', 'Dalam dunia penuh perseteruan dan intrik, seorang pejuang yang dikenal sebagai Anjing Pedang Berdarah Baja bertekad untuk membalas dendam atas kehancuran keluarganya. Dengan ketangguhan dan keahlian pedang yang luar biasa, ia menghadapi berbagai musuh dan rintangan untuk mencapai keadilan yang sejati. Perjalanannya tidak hanya membawa pertarungan yang intens, tapi juga menguji nilai kemanusiaan dan harga diri. Dalam prosesnya, ia menemukan teman serta musuh yang memperdalam makna balas dendam dan pengorbanan sejati.', '', 'https://static.wikia.nocookie.net/revenge-of-the-ironblooded-sword-hound/images/b/b3/Cover.png', NULL),
(14, 'Manga Jigokuraku (END)', 'manga-jigokuraku-end', 'Cerita ini berkisah tentang Gabimaru, seorang ninja yang terkenal karena kehebatannya dan keengganannya untuk mati, meskipun telah dijatuhi hukuman mati. Ia memulai misi berbahaya di Pulau Ibu, tempat di mana berbagai makhluk mengerikan dan ancaman mematikan menanti, dengan harapan bisa mendapatkan kebebasan dan kembali kepada istri tercintanya. Dalam perjalanan tersebut, Gabimaru bertemu dengan berbagai karakter unik dan menghadapi rintangan yang menguji kesetiaan dan kemanusiaannya. Di pulau yang penuh dengan misteri dan bahaya ini, para tahanan serta para pemburu harta karun berlomba untuk bertahan hidup dan mencapai tujuan masing-masing. Konflik yang kompleks antar karakter serta rahasia gelap di balik pulau ini perlahan terungkap, memperlihatkan sisi lain dari dunia yang keras namun penuh harapan. Cerita ini menggambarkan perjuangan manusia dalam menghadapi tantangan ekstrem sambil mempertahankan nilai-nilai kemanusiaan.', '', 'https://i.pinimg.com/736x/cd/c6/4d/cdc64d90dbdeb8b5dfeacdaa0593f007.jpg', NULL),
(15, 'Light Novel Seishun Buta Yarou (END)', 'light-novel-seishun-buta-yarou-end', 'Dalam Seishun Buta Yarou wa Bunny Girl Senpai no Yume wo Minai dikisahkan tentang Sakuta Azusagawa yang bertemu dengan aktris bernama Mai Sakurajima. Di perpustakaan yang ramai, Mai dengan pakaian kelincinya berlalu lalang tanpa gangguan, maupun rasa risih dari orang sekitar. Merasa aneh, Sakuta akhirnya menyadari, hanya dia yang bisa melihat Mai saat itu. Fenomena ini disebut, Sindrom Pubertas. Sakuta pun memilih untuk memecahkan fenomena ini dan ternyata tidak hanya Mai seorang yang menghadapi Sindrom Pubertas ini.', '', 'https://hypeabis.id/assets/content/202405150706491715731609.jpg', NULL),
(16, 'Light Novel Mushoku Tensei: Jobless Reincarnation (END)', 'light-novel-mushoku-tensei-jobless-reincarnation-end', 'Kisah ini berpusat pada seorang pria pengangguran berusia 34 tahun yang mengisolasi diri (NEET) dan tinggal di Jepang. Setelah diusir dari rumahnya pasca kematian orang tuanya, ia tewas dalam sebuah kecelakaan lalu lintas saat mencoba menyelamatkan sekelompok remaja.  Namun, kisahnya tidak berakhir di sana. Ia bereinkarnasi ke dunia sihir dan pedang, terlahir kembali sebagai seorang bayi bernama Rudeus Greyrat, putra dari Paul Greyrat, seorang pendekar pedang, dan istrinya, Zenith, seorang tabib.  Dengan mempertahankan ingatan dari kehidupan masa lalunya, Rudeus bertekad untuk menjalani hidup barunya dengan sungguh-sungguh dan tanpa penyesalan.', '', 'https://upload.wikimedia.org/wikipedia/id/f/f6/Mushoku_Tensei_1.png', NULL),
(17, 'Manga Akame ga Kill (Sub Indo) (END)', 'manga-akame-ga-kill-sub-indo-end', 'Akame ga Kill! mengikuti kisah Tatsumi, seorang pemuda desa yang pergi ke ibu kota demi mencari keberuntungan dan membantu keluarganya. Namun, dia segera menyadari bahwa kota itu penuh dengan korupsi dan ketidakadilan, sehingga ia bergabung dengan kelompok pembunuh bayaran bernama Night Raid yang bertujuan menggulingkan rezim yang zalim. Dalam perjuangan melawan kekuasaan tirani, Tatsumi dan anggota Night Raid lainnya menghadapi bahaya yang mengancam nyawa mereka. Dengan senjata unik dan kemampuan luar biasa, mereka berusaha menegakkan keadilan sekaligus mempertaruhkan segalanya untuk perubahan dan masa depan yang lebih baik.', '', 'https://www.gwigwi.com/wp-content/uploads/2021/01/cover-akame-ga-kill.png', NULL),
(18, 'Manga Kimetsu no Yaiba (END)', 'manga-kimetsu-no-yaiba-end', 'Kimetsu no Yaiba mengisahkan tentang Tanjiro Kamado, seorang anak yang kehidupannya berubah drastis ketika keluarganya dibantai oleh iblis. Satu-satunya anggota keluarga yang selamat adalah adiknya Nezuko, yang berubah menjadi iblis. Tanjiro kemudian bertekad menjadi pembasmi iblis untuk mencari cara mengembalikan Nezuko menjadi manusia dan membalas dendam keluarganya. Perjalanan Tanjiro membawanya bergabung dengan Korps Pembasmi Iblis, di mana dia menghadapi berbagai macam iblis berbahaya dan menempa keterampilannya dalam menggunakan teknik pernapasan khusus. Dalam perjalanannya, Tanjiro bertemu dengan teman-teman seperjuangan yang juga memiliki kekuatan unik, bersama-sama mereka berjuang melawan ancaman iblis yang semakin kuat dan misterius.', '', 'https://image.api.playstation.com/vulcan/ap/rnd/202309/2105/17888caa136dd07ab9980c7b042a8f6e25271d92ef8a3f1c.png', NULL),
(19, 'Manga Plunderer (END)', 'manga-plunderer-end', 'Plunderer bercerita tentang dunia pasca-kiamat yang dikuasai oleh Count atau angka yang mewakili berbagai hal, termasuk jarak tempuh seseorang atau jumlah pujian yang diterima, di mana Count nol berarti bencana bagi orang tersebut. Ceritanya mengikuti Hina yang mencari Baron Merah Legendaris atas permintaan ibunya, tetapi kemudian bertemu Licht, seorang pendekar pedang bertopeng dengan Count sangat rendah, yang identitasnya disembunyikan. Keduanya terlibat dalam konflik besar antara faksi-faksi yang memperebutkan kekuatan Count, di mana kebenaran di balik kiamat dan sistem Count ini terungkap secara bertahap.', '', 'https://upload.wikimedia.org/wikipedia/en/1/1c/Plunderer_manga%2C_volume_1.jpg', NULL),
(20, 'Manga Kawaii Da ke ja nai Shikimori-san (END)', 'manga-kawaii-da-ke-ja-nai-shikimori-san-end', 'Shikimori, pacar yang manis dan imut dari siswa SMA yang selalu sial bernama Izumi. Izumi sangat beruntung memiliki Shikimori karena saat Izumi berada dalam masalah, Shikimori berubah dari sosok yang imut menjadi sangat keren dan melindungi Izumi dengan berbagai cara, membuat Izumi dan orang-orang di sekitarnya terkesima.', '', 'https://assets.pikiran-rakyat.com/crop/0x0:0x0/720x0/webp/photo/2022/01/10/1998748289.jpg', NULL),
(21, 'Manga Yakusoku no Neverland (END)', 'manga-yakusoku-no-neverland-end', 'The Promised Neverland bercerita tentang sekelompok anak yatim piatu yang tinggal di panti asuhan Grace Field House dan menemukan bahwa tempat itu sebenarnya adalah peternakan manusia yang dikelola oleh Mama dan dikirim untuk dikonsumsi oleh para iblis.dipimpin oleh tiga sahabat, Emma, Norman, dan Ray, mereka merencanakan pelarian yang berbahaya demi menyelamatkan anak-anak lainnya dari nasib mengerikan tersebut.', '', 'https://upload.wikimedia.org/wikipedia/id/thumb/4/44/The_Promised_Neverland%2C_Volume_1.jpg/250px-The_Promised_Neverland%2C_Volume_1.jpg', NULL),
(22, 'Manga Tonari no Kaibutsu-kun (END)', 'manga-tonari-no-kaibutsu-kun-end', 'Tonari no Kaibutsu-kun, atau dikenal juga sebagai My Little Monster, menceritakan kisah romansa komedi sekolah antara Shizuku Mizutani yang dingin dan fokus pada pelajaran, serta Haru Yoshida, anak pembuat onar yang penyendiri namun memiliki sifat lembut. Hubungan mereka dimulai saat Shizuku diminta mengantarkan catatan pelajaran ke Haru yang sedang diskors, dan dari sana mereka mulai memahami satu sama lain, menghadapi tantangan sosial, dan menemukan romansa di antara teman-teman mereka yang unik.', '', 'https://blitzanime.wordpress.com/wp-content/uploads/2016/02/2abe5-tonari-no-kaibutsu-kun.jpg', NULL),
(23, 'Light Novel Rakudai Kishi no Cavalry (END)', 'light-novel-rakudai-kishi-no-cavalry-end', 'Anime Rakudai Kishi no Cavalry mengisahkan sebuah sekolah magis yang memanfaatkan sihir modern dalam pertempuran. Mereka menggunakan berbagai senjata yang merupakan perwujudan jiwa mereka untuk bertarung.  Kisah berfokus pada Kurogane Ikki, seorang siswa berbakat di sekolah ini. Ikki memiliki ambisi besar untuk menjadi Kesatria Sihir. Akan tetapi, dia sering dianggap sebagai Kesatria Gagal oleh kawan-kawannya karena tidak memiliki kekuatan sihir.  Hingga suatu hari, Ikki mendapat tantangan untuk berduel dengan Stella, putri dari negeri seberang yang sekaligus murid nomor satu di sekolah. Apa yang terjadi selanjutnya? Dapat kamu saksikan sendiri dalam anime berjudul Rakudai Kishi no Cavalry.', '', 'https://otakotaku.com/asset/img/anime/2015/10/rakudai-kishi-no-cavalry.jpg', NULL),
(24, 'Manga Returned Magic Should be Special (END)', 'manga-returned-magic-should-be-special-end', 'A Returner\'s Magic Should Be Special berlatar di dunia fantasi yang terancam oleh Labirin Bayangan. Labirin ini adalah dimensi berbahaya yang menelan umat manusia sedikit demi sedikit dan dipenuhi monster. Setelah bertarung dalam labirin selama 10 tahun dan menjadi salah satu dari enam penyintas terakhir, penyihir bernama Desir Herrman melihat dunia hancur di depan matanya.  Namun, bukannya meninggal, Desir kembali ke masa lalu, tepatnya 13 tahun sebelum peristiwa tragis itu terjadi. Ia kembali ke masa-masa awal ia masuk Akademi Hebrion, sekolah sihir paling bergengsi di dunia.', '', 'https://cdn.novelupdates.com/images/2018/12/A-Returners-Magic-Should-Be-Special.jpg', NULL),
(25, 'Anime Akame ga Kill (END)', 'anime-akame-ga-kill-end', 'Batch 24 Eps ; Akame ga Kill! adalah cerita tentang Tatsumi, seorang pemuda desa yang pergi ke ibu kota untuk mencari kekayaan demi desanya. Ia justru menemukan bahwa ibu kota sangat korup dan bergabung dengan kelompok pembunuh bayaran bernama Night Raid untuk melawannya. Night Raid berjuang melawan Kekaisaran yang dikuasai oleh perdana menteri serakah untuk mengakhiri penderitaan rakyat dan korupsi.', '', 'https://www.gwigwi.com/wp-content/uploads/2021/01/cover-akame-ga-kill.png', NULL),
(26, 'Anime Assasination Classroom (END)', 'anime-assasination-classroom-end', 'Batch 47 Eps; Assassination Classroom bercerita tentang sekelompok siswa kelas 3-E di Sekolah Menengah Kunugigaoka yang mendapat tugas untuk membunuh guru wali kelas mereka, makhluk mirip gurita super bernama Koro-sensei, yang mengancam akan menghancurkan Bumi. Jika mereka berhasil, mereka akan dihadiahi 10 miliar yen.', '', 'https://i.pinimg.com/736x/c0/3f/c5/c03fc500c8225acc31da4167fa4a98e4.jpg', NULL),
(27, 'Anime Charlotte (END)', 'anime-charlotte-end', 'Batch 13 Eps + OVA ; Charlotte bercerita tentang remaja dengan kekuatan super yang lahir karena sebuah penyakit yang muncul setelah masa pubertas. Yuu Otosaka, yang memiliki kemampuan merasuki tubuh orang lain, terpaksa bergabung dengan OSIS di Akademi Hoshinoumi setelah ketahuan oleh Nao Tomori, seorang siswi dengan kemampuan membuat dirinya tidak terlihat oleh satu orang. Bersama anggota OSIS lainnya, mereka membantu siswa yang kesulitan mengendalikan kemampuan mereka.', '', 'https://upload.wikimedia.org/wikipedia/en/thumb/5/51/Charlotte_anime.jpg/250px-Charlotte_anime.jpg', NULL),
(28, 'Manga Ragnarok Solo Leveling (OnGoing)', 'manga-ragnarok-solo-leveling-ongoing', 'Solo Leveling: Ragnarok adalah cerita sekuel dari Solo Leveling yang berfokus pada Sung Suho, putra dari Sung Jinwoo dan Cha Hae-In, di dunia di mana Gerbang dan monster kembali muncul. Setelah Jinwoo dan Hae-In menghilang, Suho menjadi hunter baru yang awalnya lemah namun bertekad untuk menjadi kuat demi melindungi dunia. Cerita ini menghadirkan petualangan baru dengan musuh-musuh baru seperti Itarim dan memperkenalkan elemen seperti Bond Skill serta konsep multiverse, mengikuti perkembangan Suho yang mirip ayahnya.', '', 'https://wallpapercave.com/wp/wp15312314.png', NULL),
(29, 'Anime Owari no Seraph (Season 1 s.d. 2) (END)', 'anime-owari-no-seraph-season-1-sd-2-end', 'Virus misterius menyebar ke seluruh dunia dan memusnahkan sebagian besar populasi manusia, kecuali anak-anak di bawah usia 13 tahun. Para vampir muncul dari kegelapan untuk menaklukkan dunia, menangkap anak-anak yang tersisa, dan menjadikan mereka ternak untuk diambil darahnya.', '', 'https://upload.wikimedia.org/wikipedia/en/4/49/Seraph_of_the_End.jpg', NULL),
(30, 'Manhwa Standard of Reincarnation (OnGoing)', 'manhwa-standard-of-reincarnation-ongoing', 'Manhwa Standard Of Reincarnation yang dibuat oleh komikus bernama Blue Jaeng-i, Kim Pyung-beom ini bercerita tentang Samion samurai terkuat. Daven adalah sepupu Samion, dan dia adalah pria setengah tak bersenjata tanpa lengan kanan.', '', 'https://static.wikia.nocookie.net/koreanwebtoons/images/6/67/Standard_of_Reincarnation.jpg', NULL),
(31, 'Novel Lord of The Mysteries (EN SUB) (END)', 'novel-lord-of-the-mysteries-en-sub-end', 'Lord of the Mysteries adalah novel fantasi-misteri berlatar di dunia bergaya era Victoria alternatif. Sebuah zaman ketika uap, mesin, senjata api, dan penemuan ilmiah hidup berdampingan dengan ritual kuno, sihir, ramuan supernatural, dan kekuatan tersembunyi.  Kisah ini mengikuti Zhou Mingrui, seorang pemuda modern yang tiba-tiba terbangun di tubuh Klein Moretti, mahasiswa miskin dari Kota Tingen. Kebingungan akan ingatan barunya bercampur dengan kenyataan bahwa dunia ini dipenuhi rahasia berbahaya: organisasi misterius, artefak terkutuk, ramuan kekuatan bernama Beyonder, dan benda-benda yang tidak seharusnya dipahami manusia biasa.  Saat Klein berusaha bertahan hidup, ia tanpa sengaja tersangkut dalam kekuatan besar yang tidak ia mengerti, termasuk sebuah ruang mistis aneh yang hanya bisa ia akses melalui mimpinya. Di sana, ia menemukan potensi untuk menjadi Beyonder, yaitu manusia yang berevolusi menggunakan ramuan khusus dan memperoleh kekuatan supernatural, dengan risiko kehilangan diri dan berubah menjadi monster.  Dalam perjalanannya, Klein terlibat dengan berbagai Gereja besar, sekte rahasia, pemburu mimpi, pembelenggu iblis, dan para penyembah entitas kosmik yang berada di balik tabir dunia. Semakin banyak misteri yang ia ungkap, semakin ia sadar bahwa dunia ini dikendalikan oleh kekuatan-kekuatan kuno yang tak terbayangkan.  Di tengah kabut sejarah, konspirasi, dan horor tak kasat mata, Klein perlahan membangun jati dirinya sebagai sebuah entitas yang kelak dikenal sebagai The Fool, kartu tarot bernomor 0 yang melambangkan awal baru, potensi tak terbatas, dan makhluk yang berjalan di antara para dewa.', '', 'https://posterspy.com/wp-content/uploads/2024/07/%D9%84%D8%B9%D9%85%D9%84-%D8%A7%D9%84%D9%81%D9%86%D9%8A-1-%D8%A8%D8%B9%D8%AF-%D8%A7%D9%84%D8%AA%D8%AD%D8%B3%D9%8A%D9%86-copy.jpg', NULL),
(32, 'Anime 86 (END)', 'anime-86-end', 'Di balik tembok perlindungan, ada 86 yang berjuang mati-matian. Lena, seorang Handler, berusaha melindungi mereka. Bersama Shinei, kapten 86, mereka melawan diskriminasi dan ketidakadilan.', '', 'https://thumbor.prod.vidiocdn.com/VHSS_huIeYlA_O7A3v_TiVYFZJY=/1280x720/filters:quality(70)/vidio-media-production/uploads/image/source/12779/e9af36.jpg', NULL),
(33, 'Anime Chainsaw-man (OnGoing)', 'anime-chainsaw-man-ongoing', 'Anime ini mengangkat cerita Denji, seorang pemuda yang bekerja sebagai pemburu iblis untuk yakuza. Untuk melunasi utang orang tuanya, Denji melakukan sejumlah tugas berbahaya yang mengharuskannya menghadapi berbagai makhluk mengerikan.', '', 'https://ih1.redbubble.net/image.3595499667.6317/flat,750x,075,f-pad,750x1000,f8f8f8.jpg', NULL),
(34, 'Anime Hyouka (END)', 'anime-hyouka-end', 'Anime bertajuk Hyouka ini merupakan salah satu karya terbaik dari Kyoto Animation, yang dirilis pada tahun 2012 silam. Dilansir dari kanal YouTube Muse Indonesia, anime ini mengisahkan tentang Oreki Houtarou, seorang murid SMA yang selalu berusaha menghemat energinya saat ingin melakukan sesuatu.', '', 'https://asset.kompas.com/crops/Ze9rRMNQa3rPpLYCoKEijQgvp2s=/0x54:1000x721/1200x800/data/photo/2023/06/22/649422e8257eb.jpg', NULL),
(35, 'Anime Kurasu no Daikirai na Joshi to Kekkon suru Koto ni Natta (OnGoing)', 'anime-kurasu-no-daikirai-na-joshi-to-kekkon-suru-koto-ni-natta-ongoing', 'Anim Kurasu no Daikirai na Joshi to Kekkon suru Koto ni Natta adalah cerita tentang Saito Houjo, seorang siswa SMA yang baru saja menikah dengan teman sekelasnya, Akane Sakuramori, yang merupakan musuh alaminya. Mereka memiliki hubungan yang tidak jujur dan saling memandang dengan ketegangan. Akane berani berkata bahwa tidak ada manfaatnya bagi mereka jika orang lain mengetahui hubungan mereka, dan Saito juga tidak ingin orang lain tahu tentang hubungan mereka.', '', 'https://ramenparados.com/wp-content/uploads/2024/06/kurakon-novel-1-jp.jpg', NULL),
(36, 'Anime Manhua The Daily Life of the Immortal King (Season 1 s.d. 4) (END)', 'anime-manhua-the-daily-life-of-the-immortal-king-season-1-sd-4-end', 'Anime yang menggabungkan genre fantasi, slice of life di lingkungan sekolah, dan elemen pertarungan. Cerita dimulai dengan Wang Ling, seorang pengembang yang telah mencapai tingkat spiritual paling tinggi sejak usia enam tahun, dan berusaha untuk menjalani kehidupan sekolah yang biasa-biasa saja, tanpa perhatian atau perhatian besar. Meskipun ia memiliki kekuatan yang sangat tinggi, Wang Ling ingin menghindari masalah dan perhatian. Namun, kekuatan yang tidak terkendali sering kali menghadanginya, dan ia harus menggunakan kekuatannya untuk melindungi teman-temannya dan dunia dari ancaman yang dihadapi oleh jin, organisasi gelap, dan kompetisi pencarian kekuatan yang sangat kompetitif di sekolah.', '', 'https://asset-2.tstatic.net/bengkulu/foto/bank/images/The-Daily-Life-of-the-Immortal-King-1.jpg', NULL),
(37, 'Anime Orb : On The Movement of The Earth (END)', 'anime-orb-on-the-movement-of-the-earth-end', 'Anime yang mengisahkan tentang seorang prodidik yang mencari raharja penelitian masternya sambil mengelabui Inquisitor. Ia belajar tentang ajaran ajaran yang dianggap heretik tentang Bumi dan Sol, dan setelah bertemu dengan seorang sarjana misterius bernama Hubert, ia mempertanyakan teori helikentrismus Hubert. Anime ini menggambarkan perjuangan Rafal dalam mempertahankan keyakinannya meskipun ada risiko tinggi dari Inquisitor dan orang-orang di sekitarnya.', '', 'https://images1.penguinrandomhouse.com/cover/9798888432624', NULL),
(38, 'Anime Fumetsu no Anata e (Season 1 s.d. 2) (END)', 'anime-fumetsu-no-anata-e-season-1-sd-2-end', 'anime yang mengisahkan tentang seorang anak laki-laki yang kesepian yang berkelana di Kutub Utara dan bertemu dengan serigala. Keduanya dengan cepat menjadi teman, bersama-sama bertahan hidup di lingkungan yang keras. Ini adalah kisah unik tentang kematian, kehidupan, reinkarnasi, dan cinta yang murni.  otakudesu.la  Anime ini menawarkan pengalaman yang mendalam dan emosional, dengan fokus pada hubungan antara karakter utama dan lingkungan yang mereka hadapi. Dengan subtitle Indonesia, para penonton dapat menikmati anime ini dengan lebih baik dan memahami konteks dan makna yang lebih dalam.', '', 'https://otakotaku.com/asset/img/anime/2021/02/fumetsu-no-anata-e-6024842639b4ep.jpg', NULL),
(39, 'Handa-Kun (END)', 'handa-kun-end', 'Handa-kun adalah anime komedi prekuel dari Barakamon yang bercerita tentang Sei Handa, seorang kaligrafer SMA yang percaya bahwa semua orang membencinya, padahal ia sebenarnya sangat dikagumi dan dianggap sebagai selebritas di sekolah. Komedi utama berasal dari kesalahpahaman Handa yang terus-menerus, di mana ia menganggap kekaguman dari teman-temannya sebagai perundungan, sementara teman-temannya justru berusaha untuk mendekatinya.', '', 'https://elexmedia.s3.amazonaws.com/product/9786230016264.jpg', NULL),
(40, 'Isekai Yakkyoku (Season 1) (END)', 'isekai-yakkyoku-season-1-end', 'Ceritanya berawal dari Kanji Yakutani, seorang peneliti farmasi ternama di Jepang modern yang meninggal karena terlalu banyak bekerja setelah sebelumnya berjuang dengan kesedihan akibat kehilangan adik perempuannya karena penyakit yang tidak dapat disembuhkan. Ia bereinkarnasi ke dunia abad pertengahan bergaya Eropa sebagai seorang anak laki-laki berusia 10 tahun bernama Falma de Medicis, putra dari keluarga apoteker istana yang bergengsi.  Di dunia barunya, Falma menyadari bahwa praktik medis sangat terbelakang, penuh dengan pengobatan yang meragukan, dan hanya dapat diakses oleh kaum bangsawan. Dengan pengetahuan farmasi modern dari kehidupan masa lalunya dan kemampuan magis barunya (yang memungkinkannya menciptakan atau menghancurkan materi secara instan, serta mendiagnosis penyakit secara akurat), Falma memutuskan untuk merevolusi dunia medis di sana.  Ia mendapatkan pengakuan dari istana kekaisaran dan akhirnya membuka apoteknya sendiri, Isekai Yakkyoku. Tujuannya adalah membuat obat-obatan yang aman, efektif, dan terjangkau dapat diakses oleh semua orang, termasuk rakyat jelata di Kekaisaran San Fleuve.', '', 'https://upload.wikimedia.org/wikipedia/id/c/ca/Isekai_Yakkyoku_light_novel_volume_1_cover.jpg', NULL),
(41, 'Kamen Rider Ex-Aid True Ending (END)', 'kamen-rider-ex-aid-true-ending-end', 'Cerita dimulai ketika wabah Penyakit Game baru melanda Tokyo, mendorong Emu Hojo dan para Dokter Rider dari CR (Cyberbrain Rescue) untuk menyelidiki. Mereka menemukan bahwa dalang di balik wabah baru ini adalah perusahaan video game asing bernama Machina Vision, yang dipimpin oleh CEO Johnny Maxima dan eksekutif Kagenari Nagumo.  Tujuan Nagumo adalah untuk memindahkan kesadaran manusia ke dunia realitas virtual (VR) untuk menciptakan', '', 'https://m.media-amazon.com/images/M/MV5BZjE0MTYzMzEtOGNjZC00MjY2LWI2NTAtNGNjYWQwMDFhN2M5XkEyXkFqcGc@._V1_.jpg', NULL),
(42, 'Kamen Rider Zi-O Over Quartzer (END)', 'kamen-rider-zi-o-over-quartzer-end', 'Film Kamen Rider Zi-O the Movie: Over Quartzer mengisahkan tentang perjalanan waktu Sougo Tokiwa dan teman-temannya ke abad ke-16 di Jepang, di mana mereka terlibat dalam konspirasi besar yang menguji takdir Sougo sebagai raja waktu', '', 'https://m.media-amazon.com/images/M/MV5BM2ZlOGMyMWItNTExMy00MTQ0LWIzM2ItODU2NWRiMDk2MTRiXkEyXkFqcGc@._V1_.jpg', NULL),
(43, 'Ron Kamonohashi no Kindan Suiri (Season 1 s.d. 2) (END)', 'ron-kamonohashi-no-kindan-suiri-season-1-sd-2-end', 'Ron Kamonohashi no Kindan Suiri (Ron Kamonohashi\'s Forbidden Deductions) bercerita tentang Ron Kamonohashi, seorang detektif jenius eksentrik yang dilarang menjadi detektif, dan Totomaru Isshiki (Toto), seorang detektif polisi yang tulus namun tidak terampil. Lima tahun sebelum cerita dimulai, Ron adalah siswa terbaik di Akademi Pelatihan Detektif BLUE, sebuah institusi elit. Namun, setelah dituduh bertanggung jawab atas insiden mematikan yang dikenal sebagai', '', 'https://image.idntimes.com/post/20230805/f1erqvyaaaa-wj4-313825f86cbed6855e17bc2500a46997-b4fe0151de70e1bec9e4b339be606881.jpg', NULL),
(44, 'Kimi no Nawa (END)', 'kimi-no-nawa-end', 'Kimi no Na wa (Your Name) adalah film fantasi romantis animasi Jepang yang bercerita tentang dua remaja, Mitsuha Miyamizu dan Taki Tachibana, yang mendapati diri mereka bertukar tubuh secara misterius. Mitsuha adalah seorang gadis SMA yang tinggal di desa terpencil bernama Itomori dan merindukan kehidupan di kota besar Tokyo, sementara Taki adalah seorang siswa SMA di Tokyo yang menjalani kehidupan kota yang sibuk.', '', 'https://upload.wikimedia.org/wikipedia/id/0/0b/Your_Name_poster.png', NULL),
(45, 'Loop 7-kaime no Akuyaku Reijou wa, Moto Tekikoku de Jiyuu Kimama na Hanayome Seikatsu wo Mankitsu suru (END)', 'loop-7-kaime-no-akuyaku-reijou-wa-moto-tekikoku-de-jiyuu-kimama-na-hanayome-seikatsu-wo-mankitsu-suru-end', 'Rishe telah menjalani enam kehidupan yang berbeda sebelumnya, mencoba berbagai peran seperti pedagang, apoteker, pelayan, dan ksatria, dan mengumpulkan berbagai pengetahuan serta keterampilan dari setiap kehidupan tersebut. Dalam putaran ketujuh ini, Rishe bertekad untuk menghindari kematiannya dan menjalani kehidupan yang lebih bebas dan damai, memanfaatkan semua pengalaman dari kehidupan sebelumnya. Namun, takdir kembali mempertemukannya dengan Pangeran Arnold Hein, putra mahkota dari kekaisaran musuh yang bertanggung jawab atas perang dan kematiannya di kehidupan-kehidupan sebelumnya. Secara mengejutkan, Pangeran Arnold melamarnya. Rishe, yang melihat ini sebagai kesempatan unik untuk mendekati musuh bebuyutannya, menerima lamaran tersebut dengan tujuan untuk mencegah perang yang akan datang dari dalam kekaisaran musuh.', '', 'https://otakotaku.com/asset/img/anime/2023/12/loop-7-kaime-no-akuyaku-reijou-658c2d644c07ep.jpg', NULL),
(46, 'Maou Gakuin no Futekigousha (Season 1 s.d. 3) (END)', 'maou-gakuin-no-futekigousha-season-1-sd-3-end', 'Maou Gakuin no Futekigousha (The Misfit of Demon King Academy) mengisahkan tentang Anos Voldigoad, Raja Iblis tiran yang hidup 2.000 tahun yang lalu, yang bosan dengan perang yang menghancurkan dan memutuskan untuk bereinkarnasi demi mencari kedamaian. Dua milenium kemudian, Anos bereinkarnasi ke dunia di mana sihir telah mengalami kemunduran drastis dan keturunannya menjadi lemah karena kepuasan diri. Dia kemudian mendaftar di Akademi Raja Iblis, sebuah institusi yang didirikan untuk melatih dan mengidentifikasi reinkarnasi Raja Iblis Tirani yang sebenarnya.  Namun, karena kekuatan magisnya yang luar biasa besar dan di luar nalar, akademi tidak dapat mengukur kekuatannya dengan benar, yang menyebabkan dia dicap sebagai siswa yang tidak cocok atau misfit. Anos, yang sebenarnya adalah Raja Iblis asli, mendapati dirinya diremehkan dan dianggap remeh oleh keturunan iblis modern yang sombong, yang sebagian besar memiliki darah murni dan mengagungkan status keturunan.', '', 'https://upload.wikimedia.org/wikipedia/id/7/76/The_Misfit_of_Demon_King_Academy_light_novel_volume_1_cover.jpg', NULL),
(47, 'Light Novel Story Line Maou Gakuin no Futekigousha (Volume s.d. 14) (END)', 'light-novel-story-line-maou-gakuin-no-futekigousha-volume-sd-14-end', 'Maou Gakuin no Futekigousha Volume 14 menceritakan serangan Anos ke Dunia Peluru Ajaib untuk menyelamatkan Misha dan Sasha yang terperangkap di sana. Setelah Misha dan Sasha berhasil menyusup, mereka bertemu dengan Elenesia, Dewi Pencipta sebelumnya dan ibu mereka, yang mengungkapkan rahasia tentang sihir penghancur perak dan bagaimana dunia itu sendiri menjadi \"peluru\". Untuk mengubah takdirnya, Elenesia menantang Dewa Tertinggi, dengan kunci kemenangan terletak pada kekuatan yang ditinggalkan oleh Raja Iblis Kedua (Anos).', '', 'https://static.wikia.nocookie.net/maou-gakuin/images/5/51/Volume_15_Cover_Textless.jpg', NULL),
(48, 'Munou na Nana (END)', 'munou-na-nana-end', 'Film Munou na Nana sendiri berlatarkan di tahun 20XX yang menceritakan Bumi telah diserang oleh monster yang dikenal sebagai musuh umat manusia. Untuk menghadapi ancaman itu, sekolah khusus pun didirikan yang terdiri atas sekelompok remaja dengan kemampuan luar biasa dibentuk.  Mereka pun dikenal sebagai orang Yang Berbakat, dengan kemampuan untuk menentang aturan realita. Meski demikian, terdapat seseorang yang dikirimkan ke salah satu sekolah ini, namun dirinya tidak memiliki kemampuan khusus apa pun.', '', 'https://otakotaku.com/asset/img/anime/2020/09/munou-na-nana-5f582187458a4p.jpg', NULL),
(49, 'One Punch Man (Season 1 s.d. 2) (END)', 'one-punch-man-season-1-sd-2-end', 'One-Punch Man mengisahkan Saitama, seorang pahlawan independen yang dapat mengalahkan musuh mana pun hanya dengan satu pukulan. Karena kekuatannya yang luar biasa, ia merasa sangat bosan dan hampa, serta terus mencari lawan yang lebih kuat untuk merasakan kembali adrenalin dan sensasi pertarungan yang menantang.', '', 'https://www.viu.com/ott/id/articles/wp-content/uploads/2021/01/anime-one-punch-man-season-2-sub-indo-viu.jpg', NULL),
(50, 'Oregairu (Season 1 s.d. 3) (END)', 'oregairu-season-1-sd-3-end', 'Oregairu, singkatan dari Yahari Ore no Seishun Love Come wa Machigatteiru (My Teen Romantic Comedy SNAFU), mengisahkan tentang Hachiman Hikigaya, seorang siswa SMA pesimistis dan antisosial yang dipaksa bergabung dengan Klub Relawan Jasa. Di klub ini, ia bertemu dengan dua gadis yang juga penyendiri, dan bersama-sama mereka membantu siswa lain sambil menghadapi konflik batin mereka sendiri.', '', 'https://static.wikia.nocookie.net/yahari/images/4/40/Oregairu.png', NULL),
(51, 'Death Parade (END)', 'death-parade-end', 'Ketika dua orang meninggal pada saat yang bersamaan, mereka tidak langsung pergi ke surga atau neraka, melainkan dikirim ke salah satu dari banyak bar misterius yang berfungsi sebagai purgatorium (api penyucian). Bar-bar ini dijalankan oleh bartender yang dikenal sebagai arbiter atau hakim jiwa. Di bar tersebut, para tamu yang baru meninggal, tanpa ingatan tentang kematian mereka, dipaksa untuk berpartisipasi dalam Death Game. Permainan ini, yang sering kali mengambil bentuk permainan bar biasa seperti dart atau bowling, dirancang untuk mendorong para peserta ke dalam situasi ekstrem di mana sifat asli, ingatan tersembunyi, dan sisi gelap kemanusiaan mereka terungkap. Decim, bartender berambut putih di bar Quindecim (di lantai 15), adalah salah satu arbiter tersebut. Tugasnya adalah mengamati perilaku para tamu selama permainan untuk menilai jiwa mereka. Berdasarkan hasil pengamatan tersebut, Decim memutuskan nasib jiwa mereka: apakah akan dikirim untuk bereinkarnasi (kehidupan baru) atau dibuang ke dalam kehampaan (ketiadaan). Alur cerita utama dimulai ketika seorang wanita berambut hitam misterius tiba di Quindecim, juga tanpa ingatan, tetapi berbeda dari tamu biasa karena ia mengetahui bahwa ia sudah mati. Ia menjadi asisten Decim dan dijuluki wanita berambut hitam. Kehadiran dan interaksinya dengan Decim mulai menantang pandangan Decim yang tampak tanpa emosi terhadap penilaian jiwa manusia, memaksa Decim dan penonton untuk mempertanyakan keadilan dari sistem penghakiman yang mekanis dan dingin tersebut.', '', 'https://upload.wikimedia.org/wikipedia/id/thumb/c/c3/Deathparadevisual.jpg/250px-Deathparadevisual.jpg', NULL),
(52, 'Danjo no Yuujou wa Seiritsu suru? Iya, Shinai!! atau Can a Boy-Girl Friendship Survive? No, It Cant! (END)', 'danjo-no-yuujou-wa-seiritsu-suru-iya-shinai-atau-can-a-boy-girl-friendship-survive-no-it-cant-end', 'Kisah ini mengikuti kehidupan Yu Natsume, seorang anak laki-laki, dan Himari Inuzuka, seorang anak perempuan, yang telah mengikrarkan persahabatan abadi sejak mereka pertama kali bertemu di sebuah festival SMP. Mereka menikmati masa-masa kebersamaan mereka sebagai teman baik dan tergabung dalam klub berkebun di SMA mereka di pedesaan.  Namun, hubungan persahabatan murni mereka mulai menghadapi turbulensi ketika Yu bertemu kembali dengan cinta pertamanya di SMA. Himari, yang belum pernah merasakan apa itu cinta romantis, mulai mempertanyakan perasaannya sendiri terhadap Yu saat kecurigaan muncul bahwa Yu mungkin memiliki perasaan terhadap gadis lain bernama Rion Enomoto.  Cerita ini mengeksplorasi tantangan dan kerumitan dalam menjaga persahabatan antara laki-laki dan perempuan ketika perasaan romantis dan kecemburuan mulai ikut campur, menguji impian bersama dan hari-hari damai mereka sebagai duo klub berkebun.', '', 'https://static.wikia.nocookie.net/danjoru/images/5/54/Anime_Key_Visual_3.png', NULL),
(53, 'Oroka na Tenshi wa Akuma to Odoru (END)', 'oroka-na-tenshi-wa-akuma-to-odoru-end', 'anime tentang Masatora Akutsu, seorang iblis yang menyusup ke sekolah manusia untuk menemukan kandidat untuk membantu Neraka melawan Surga. Misinya adalah merekrut seorang siswa bernama Lily Amane, tetapi ia malah menemukan bahwa Lily memiliki rahasia tersembunyi dan perasaannya sendiri berkembang untuknya, membuatnya dalam posisi yang rumit.', '', 'https://otakotaku.com/asset/img/anime/2023/10/oroka-na-tenshi-wa-akuma-to-odoru-65366e16d638bp.jpg', NULL),
(54, 'Rokudenashi Majutsu Koushi to Akashic Records (END)', 'rokudenashi-majutsu-koushi-to-akashic-records-end', 'Berlatar di Kekaisaran Alzano, rumah bagi Akademi Sihir Kekaisaran Alzano yang bergengsi, cerita ini berpusat pada seorang instruktur pengganti yang malas dan tampaknya tidak kompeten bernama Glenn Radars.', '', 'https://s1.zerochan.net/Rokudenashi.Majutsu.Koushi.to.Kinki.Kyouten.600.3365750.jpg', NULL),
(55, 'Tokidoki Bosotto Roshiago de Dereru Tonari no Alya-san atau Alya Sometimes Hides Her Feelings in Russian (Season 1 s.d. 2) (END)', 'tokidoki-bosotto-roshiago-de-dereru-tonari-no-alya-san-atau-alya-sometimes-hides-her-feelings-in-russian-season-1-sd-2-end', 'sebuah serial komedi romantis yang berfokus pada dinamika hubungan antara Alisa Mikhailovna Kujo (Alya), seorang siswi populer keturunan Rusia-Jepang, dan teman sebangkunya yang tampak biasa dan tidak termotivasi, Masachika Kuze.', '', 'https://static.wikia.nocookie.net/roshidere/images/3/3c/Roshidere_Season_2_Visual_1.png', NULL),
(56, 'Sakamoto Days (END)', 'sakamoto-days-end', 'Sakamoto Days menceritakan kisah Taro Sakamoto, seorang mantan pembunuh bayaran legendaris yang telah pensiun demi menjalani kehidupan normal sebagai kepala keluarga dan pemilik toko kelontong. Kehidupan damainya terganggu ketika masa lalunya terungkap, memaksanya untuk kembali menggunakan keterampilan bertarungnya demi melindungi keluarganya dari ancaman para pembunuh bayaran lain yang datang untuk memburunya.', '', 'https://image.gramedia.net/rs:fit:0:0/plain/https://cdn.gramedia.com/uploads/picture_meta/2023/1/20/qfab596eeqxvev9prt2kcm.jpg', NULL),
(57, 'Satsuriku no Tenshi (END)', 'satsuriku-no-tenshi-end', 'Satsuriku no Tenshi (atau Angels of Death) adalah serial anime horor psikologis yang mengisahkan tentang Rachel Gardner, seorang gadis berusia 13 tahun yang terbangun di lantai bawah tanah sebuah bangunan misterius tanpa ingatan apa pun tentang masa lalunya.', '', 'https://www.gwigwi.com/wp-content/uploads/2021/02/cover-satsuriku-no-tenshi-460x600.jpg', NULL),
(58, 'Sekai Saikou no Ansatsusha, Isekai Kizoku ni Tensei suru (END)', 'sekai-saikou-no-ansatsusha-isekai-kizoku-ni-tensei-suru-end', 'Serial anime dan novel ringan Sekai Saikou no Ansatsusha, Isekai Kizoku ni Tensei suru (The World\'s Finest Assassin Gets Reincarnated in Another World as an Aristocrat) mengisahkan tentang seorang pembunuh bayaran legendaris yang bereinkarnasi ke dunia sihir dengan sebuah misi baru: membunuh pahlawan yang ditakdirkan untuk menghancurkan dunia', '', 'https://upload.wikimedia.org/wikipedia/id/1/1d/The_World%27s_Finest_Assassin_Gets_Reincarnated_in_a_Different_World_as_an_Aristocrat_volume_1.jpg', NULL),
(59, 'Servamp (END)', 'servamp-end', 'Sinopsis Servamp berpusat pada Mahiru Shirota, seorang siswa SMA yang menyukai kesederhanaan, yang secara tidak sengaja membentuk kontrak dengan vampir bernama Kuro. Kuro sebenarnya adalah salah satu dari tujuh vampir yang mewakili tujuh dosa pokok, dikenal sebagai Servamp. Setelah membentuk kontrak, Mahiru menjadi Eve (tuan), dan mereka terjerat dalam perang antar-vampir yang dimulai oleh Tsubaki, Servamp kedelapan yang memicu konflik.', '', 'https://otakotaku.com/asset/img/anime/2016/05/servamp.jpg', NULL),
(60, 'Summer Pockets', 'summer-pockets', 'Summer Pockets adalah sebuah kisah tentang seorang pemuda bernama Hairi Takahara yang pergi ke pulau terpencil Torishirojima untuk mengurus warisan neneknya setelah mengalami insiden di kota. Setibanya di sana, ia bertemu dengan empat gadis unik: Shiroha Naruse, Ao Sorakado, Kamome Kushima, dan Tsumugi Wenders. Saat menghabiskan musim panas bersama mereka, Hairi mulai beradaptasi dengan kehidupan pulau dan kenangan yang terlupakan perlahan kembali.', '', 'https://upload.wikimedia.org/wikipedia/en/thumb/1/17/Summer_Pockets_game_cover.jpg/250px-Summer_Pockets_game_cover.jpg', NULL),
(61, 'Vanitas No Carte (END)', 'vanitas-no-carte-end', 'Vanitas no Carte menceritakan tentang Vanitas, seorang manusia yang memiliki buku sihir kuno bernama Kitab Vanitas, yang digunakan untuk menyembuhkan vampir dari kutukan yang membuat mereka gila dan haus darah. Dia bekerja sama dengan seorang vampir muda bernama Noe untuk menyembuhkan vampir-vampir terkutuk di Paris abad ke-19, di mana latar belakang steampunk dan tema vampir menjadi elemen utama dalam cerita.', '', 'https://i.ebayimg.com/images/g/1A8AAOSwhfRjEA6V/s-l400.jpg', NULL);
INSERT INTO `komik` (`id`, `judul`, `slug`, `penulis`, `penerbit`, `gambar`, `tahun_terbit`) VALUES
(62, 'Violet Evergarden (END)', 'violet-evergarden-end', 'Violet Evergarden mengisahkan perjalanan seorang mantan prajurit muda pascaperang yang beradaptasi dengan kehidupan sipil sebagai Auto Memory Doll, atau penulis surat, untuk memahami arti kata-kata terakhir yang diucapkan kepadanya: Aku mencintaimu.  Violet, yang dibesarkan hanya sebagai alat perang tanpa emosi, bergabung dengan Perusahaan Pos C.H. atas permintaan rekan mendiang Mayor Gilbert Bougainvillea, orang yang paling berarti baginya. Melalui pekerjaannya, ia melakukan perjalanan dan bertemu dengan berbagai klien yang memiliki kisah hidup menyentuh, membantunya menuliskan perasaan terdalam mereka ke dalam surat.', '', 'https://blue.kumparan.com/image/upload/fl_progressive,fl_lossy,c_fill,f_auto,q_auto:best,w_640/v1634547006/tlggf5t6cnciemq2amsd.jpg', NULL),
(63, 'Upin & Ipin Geng Pengembara Bermula', 'upin-ipin-geng-pengembara-bermula', 'bercerita tentang seorang remaja bernama Badrol yang mengunjungi neneknya, Tok Dalang, di sebuah desa yang dikenal sebagai Kampung Durian Runtuh. Di sana, keadaan menjadi tidak tenang karena ada makhluk berbahaya yang berkeliaran malam hari. Namun, ketenangan itu berubah ketika Badrol, teman sekelasnya Lim, Rajoo, dan dua adik desa, Upin dan Ipin, menemukan pusat misteri tersebut. Mereka berusaha untuk menemukan jawaban atas kejadian yang menakutkan di desa tersebut.', '', 'https://i1.wp.com/p16.resso.me/img/tos-alisg-v-2102/db4b0d0716664ca5beec97e49b8cbab0~c5_500x500.jpg', NULL),
(64, 'Upin & Ipin Keris Siamang Tunggal', 'upin-ipin-keris-siamang-tunggal', 'mengisahkan petualangan sepasang saudara kembar, Upin dan Ipin, serta enam sahabat mereka, Ehsan, Fizi, Mail, Jarjit, Mei Mei, dan Susanti. Mereka menemukan sebuah keris mistik di gudang Tok Dalang yang membuka portal ke kerajaan fantasi Inderaloka. Dalam perjalanan mereka, mereka bertemu dengan karakter klasik dari cerita rakyat Malaysia seperti Mat Jenin dan Belalang, serta harus bekerja sama untuk mempertahankan kerajaan dari Raja Bersiong yang jahat. Film ini mengandung pesan moral tentang persahabatan dan kebaikan.', '', 'https://carifilms.com/wp-content/uploads/2019/10/MV5BZGJjMTAxZmQtYWZhYS00MTFjLTgzYzktMjIyMWE2ZTk4NjZjXkEyXkFqcGdeQXVyMTAwNTk4Mjg5._V1_UX182_CR00182268_AL_.jpg', NULL),
(65, 'Ejen Ali Series', 'ejen-ali-series', 'Sinopsis Ejen Ali mengisahkan tentang seorang anak bernama Ali yang secara tidak sengaja terjebak dalam dunia intelijen. Dalam film ini, Ali harus menghadapi ancaman dari kelompok penjahat siber yang dipimpin oleh Neonimus, sambil dibantu oleh rekannya seperti Ejen Alicia dan Ejen Bakar. Mereka berusaha mengungkap kejahatan yang semakin merajalela di kota Cyberaya, terutama setelah Ali mencoba teknologi baru bernama IRIS NEO yang mengubah perannya sebagai agen.', '', 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjpBqvz_WHk6wcJL6pp0kuL_AnWC4iCRz2ZncuqBT8EwCqqiBj9ktCADTYkMSW73AY6Oiob3OYV7obU5tFwDBS4pTHC9Cp6uee_VC8W9ZKy5Y-AbfJcPYuby-OG6pu3TNlBJ-4iZIxXRMe-VTwGyGPpoK1ItTb8LO2CgnIB4b_3Zx5E-HnLUlQoIr2XUfQ/s1351/Poster-2-EATM2.png', NULL),
(66, 'Avengers: Infinity War', 'avengers-infinity-war', 'Film Avengers: Infinity War mengisahkan kisah kelanjutan petualangan para superhero yang tergabung dalam tim Avengers. Para anggota tim tersebut akan berhadapan dengan musuh yang berusaha menghancurkan bumi, yaitu Thanos. Tim Avengers ini mengalami kesulitan karena Thanos memiliki tentara alien yang kuat dengan jumlah yang banyak. Meskipun demikian, mereka harus berusaha keras melawan Thanos hingga tiba bantuan dari tim Guardian of the Galaxy.', '', 'https://cdn.antaranews.com/cache/1200x800/2018/04/avengers.jpg', NULL),
(67, 'Avengers: END GAME', 'avengers-end-game', 'Avengers: Endgame adalah film pahlawan super yang mengisahkan perjuangan para Avengers untuk membalikkan kehampaan yang ditimbulkan oleh Thanos, setelah setengah populasi dunia lenyap akibat jentikan jarinya.', '', 'https://m.media-amazon.com/images/I/810U4ZY+tfL._AC_UF1000,1000_QL80_.jpg', NULL),
(68, 'Interstellar', 'interstellar', 'Interstellar adalah film fiksi ilmiah yang disutradarai oleh Christopher Nolan, yang mengisahkan perjalanan luar angkasa untuk menyelamatkan umat manusia di tengah krisis ekologi di Bumi. Latar Belakang Film ini berlatar pada tahun 2067, di mana Bumi mengalami kekurangan sumber daya, badai debu, dan wabah penyakit yang mengancam kelangsungan hidup manusia. Tanaman gagal panen, dan umat manusia terpaksa kembali ke cara hidup pertanian tradisional.', '', 'https://www.slashfilm.com/wp/wp-content/images/interstellar-final-trailer.jpg', NULL),
(69, 'Pacific Rim 2013', 'pacific-rim-2013', 'Pacific Rim adalah film aksi dan fiksi ilmiah yang dirilis pada tahun 2013, disutradarai oleh Guillermo del Toro. Cerita berlatar di masa depan, ketika Bumi diserang oleh makhluk raksasa yang dikenal sebagai Kaiju, yang muncul dari celah antardimensi di dasar Samudra Pasifik. Untuk melawan ancaman ini, manusia menciptakan robot raksasa yang disebut Jaeger, yang dikendalikan oleh dua pilot melalui koneksi mental. Film ini menggambarkan pertempuran antara umat manusia dan monster laut yang semakin kuat, serta tema kerjasama dan pengorbanan demi kehidupan di Bumi.', '', 'https://i.pinimg.com/736x/4f/f9/e6/4ff9e6f25a618ffb21cd7bded1014016.jpg', NULL),
(70, 'KungFu Panda', 'kungfu-panda', 'Kung Fu Panda adalah film animasi komedi seni bela diri yang menggabungkan humor, aksi, dan nilai-nilai inspiratif. Cerita dimulai di Lembah Damai, sebuah negeri di Tiongkok kuno yang dihuni oleh binatang-binatang antropomorfik. Po, seorang panda raksasa yang mengidolakan Furious Five, terpilih sebagai Naga Sakti dan dianggap tidak layak untuk belajar kung fu. Namun, setelah melihat Tai Lung, seorang macan tutul salju yang tidak terpilih, Po mulai percaya diri dan berjuang untuk memenuhi takdirnya. Film ini juga menggambarkan perjalanan seorang underdog yang menemukan kekuatan sejatinya melalui kerja keras, humor, dan keberanian.', '', 'https://wallpapers.com/images/hd/kung-fu-panda-sliding-around-on-wheelbarrow-zwm61o41mr0w4ws6.jpg', NULL),
(71, 'Jenderal Soedirman', 'jenderal-soedirman', 'Film ini disutradarai oleh Viva Westi dan dirilis pada tahun 2015. Cerita berfokus pada Jenderal Soedirman, seorang pemimpin perang gerilya yang berjuang meskipun menderita penyakit paru-paru. Film ini menggambarkan periode penting dalam sejarah Indonesia, khususnya saat Agresi Militer Belanda II pada 19 Desember 1948, ketika Belanda menyerang Yogyakarta, yang saat itu merupakan ibu kota Republik Indonesia. Presiden Soekarno dan Wakil Presiden Mohammad Hatta ditangkap dan diasingkan ke Pulau Bangka.', '', 'https://static.uc.ac.id/library/2018/08/movie-time_-Jendral-Sudirman.jpg', NULL),
(72, 'Battle of Surabaya', 'battle-of-surabaya', 'Mengisahkan tentang peristiwa pertempuran 10 November 1945 di Surabaya. Cerita dimulai dengan visualisasi pengeboman kota Hiroshima dan Nagasaki oleh Sekutu, yang menandakan menyerahnya Jepang. Musa, seorang remaja tukang semir sepatu, terlibat sebagai kurir rahasia untuk para pejuang. Ia mengalami berbagai tragedi dan kehilangan orang-orang tersayang demi mempertahankan kemerdekaan Indonesia. Pertempuran Surabaya adalah perang pertama bangsa Indonesia setelah proklamasi kemerdekaan pada 17 Agustus 1945. Film ini menggambarkan perjuangan Musa dan arek-arek Suroboyo dalam melawan penjajahan.', '', 'https://thumb.viva.co.id/media/frontend/thumbs3/2015/09/02/334085_battle-of-surabaya_665_374.jpg', NULL),
(73, 'Battle of Berlin', 'battle-of-berlin', 'Pertempuran Berlin adalah salah satu pertempuran terakhir dari Teater Eropa Perang Dunia II. Pertempuran ini berlangsung dari akhir April 1945 sampai awal Mei. Sebelum pertempuran berakhir, Adolf Hitler telah bunuh diri tepatnya 30 April 1945, dua hari setelah eksekusi Benito Mussolini. Jerman menyerah setelah lima hari pertempuran. Penyerahan Jerman ditandatangani oleh Marsekal Wilhelm Keitel. Selanjutnya Berlin dibagi dua, yakni Berlin Timur milik Soviet dan Berlin Barat milik Amerika, Inggris, dan Prancis. Kota Berlin mengalami kerusakan yang parah meskipun beberapa bangunan seperti Gerbang Brandenburg dan Gedung Reichstag masih bertahan. Setelah Keitel menandatangani instrumen penyerahan, dilanjutkan dengan Pengadilan Nuremberg.', '', 'https://pictures.abebooks.com/isbn/9780752446820-us.jpg', NULL),
(74, 'Sang Kiai', 'sang-kiai', 'Film Sang Kiai mengisahkan masa hidup Kyai Hasyim Asyari yang berat pada masa perjuangan di Indonesia. Film ini berlatar tahun 1942, saat Jepang melakukan ekspansi ke Indonesia dan melarang pengibaran bendera merah putih serta pemutaran lagu Indonesia Raya.', '', 'https://vidiodotcom.wpcomstaging.com/wp-content/uploads/2022/01/Sang-Kiai-Thumbnail.jpg', NULL),
(75, 'Fetih: Fall of Constantinople 1453', 'fetih-fall-of-constantinople-1453', 'Film Fetih 1453, disutradarai oleh Faruk Aksoy, mengisahkan penaklukan Konstantinopel oleh Kesultanan Utsmaniyah pada tahun 1453. Film ini dimulai dengan Sultan Mehmed II yang mempersiapkan serangan untuk merebut kota tersebut. Dalam film ini, para pejuang Utsmaniyah harus menghadapi pertahanan yang kuat dari tentara Bizantium, termasuk penggunaan tembok pelindung yang sangat tinggi. Film ini juga menampilkan kisah cinta antara seorang prajurit Utsmaniyah bernama Ulubatlı Hasan dan putri dari Kaisar Konstantinus XI bernama Era', '', 'https://alchetron.com/cdn/fetih-1453-81148746-afad-4f40-a909-587e7d4a870-resize-750.jpeg', NULL),
(76, 'Uchuu Sentai Kyuuranger', 'uchuu-sentai-kyuuranger', 'Uchuu Sentai Kyuuranger adalah seri Super Sentai ke-41 yang mengangkat tema angkasa luar, rasi bintang, dan nasib yang ditentukan oleh keberuntungan (luck).  Di masa depan, alam semesta dikuasai oleh organisasi tirani bernama Jark Matter, yang menindas planet-planet dan penduduknya dengan kekuatan absolut. Harapan terakhir berada pada kelompok pemberontak bernama Rebellion, yang percaya pada ramalan kuno: Sembilan pahlawan akan muncul untuk mengubah takdir semesta.', '', 'https://static.wikia.nocookie.net/powerrangers/images/c/cc/Kyuranger_DVD_01.jpg', NULL),
(77, 'Kaitou Sentai Lupinranger vs Keisatsu Sentai Patranger', 'kaitou-sentai-lupinranger-vs-keisatsu-sentai-patranger', 'Dahulu, seorang pencuri legendaris bernama Arsene Lupin mengumpulkan harta ajaib bernama Lupin Collection. Kumpulan artefak ini memiliki kekuatan luar biasa yang dapat mengubah dunia. Namun, harta itu dicuri oleh organisasi kriminal dari dimensi lain bernama Ganglers. Untuk merebutnya kembali, trio pencuri elegan Lupinranger muncul.', '', 'https://static.wikia.nocookie.net/powerrangers/images/6/6e/LuPat_Final_Tour_Poster.jpg', NULL),
(78, 'NARUTO', 'naruto', 'Naruto Uzumaki adalah anak yatim yang dikucilkan penduduk Desa Konoha karena di dalam tubuhnya disegel Kyūbi—Rubah Ekor Sembilan yang dulu menyerang desa. Meski dihindari banyak orang, Naruto bermimpi menjadi Hokage, pemimpin desa yang dihormati.', '', 'https://upload.wikimedia.org/wikipedia/id/9/94/NarutoCoverTankobon1.jpg', NULL),
(79, 'Naruto Shippuden', 'naruto-shippuden', 'Setelah berlatih, Naruto kembali ke Konoha dengan kekuatan baru. Dunia ninja mulai diguncang oleh organisasi kriminal berbahaya: Akatsuki.', '', 'https://upload.wikimedia.org/wikipedia/id/a/ad/Naruto_-_Shippuden_DVD_season_1_volume_1.jpg', NULL),
(80, 'Kisah Walisongo', 'kisah-walisongo', 'Walisongo adalah sekelompok sembilan ulama besar yang berperan penting dalam penyebaran Islam di Jawa pada abad ke-15 hingga 16 M. Mereka tidak hanya berdakwah, tetapi juga membangun pondasi sosial, budaya, dan pendidikan masyarakat Jawa sehingga Islam dapat diterima tanpa pertentangan besar.', '', 'https://upload.wikimedia.org/wikipedia/id/thumb/5/54/Poster_Kisah_9_Wali.jpg/330px-Poster_Kisah_9_Wali.jpg', NULL),
(81, 'Kun Anta', 'kun-anta', 'Cerita Kun Anta berfokus pada kehidupan seorang anak laki-laki bernama Zaidan (dalam beberapa musim memakai nama karakter berbeda, tetapi tema tetap sama), yang menjalani keseharian di sebuah pesantren modern. Ia harus beradaptasi dengan lingkungan baru, bertemu banyak teman dengan karakter unik, dan belajar tentang arti persahabatan, kejujuran, tanggung jawab, serta menjadi diri sendiri.', '', 'https://upload.wikimedia.org/wikipedia/id/thumb/f/f0/Poster_Kun_Anta.jpeg/250px-Poster_Kun_Anta.jpeg', NULL),
(82, 'Pada Zaman Dahulu', 'pada-zaman-dahulu', 'Pada Zaman Dahulu bercerita tentang dua bersaudara, Amin dan Aminah, yang tinggal bersama Opah (Nenek) selama liburan sekolah. Setiap hari, Opah menceritakan kisah-kisah dongeng Melayu klasik kepada cucu-cucunya—cerita yang dimulai dengan kalimat khas Pada Zaman Dahulu', '', 'https://upload.wikimedia.org/wikipedia/id/7/7c/Pada_Zaman_Dahulu.jpeg', NULL),
(83, 'Liberation (1969–1971)', 'liberation-19691971', 'Liberation adalah seri film perang epik Soviet yang dirilis dalam lima bagian antara 1969–1971, disutradarai oleh Yuri Ozerov. Film ini menggambarkan Perang Dunia II dari perspektif Uni Soviet, khususnya pertempuran di front Timur melawan Nazi Jerman, dan menekankan keberanian serta pengorbanan tentara dan rakyat Soviet.', '', 'https://a.ltrbxd.com/resized/film-poster/3/5/8/8/3/2/358832-liberation-battle-for-berlin-0-230-0-345-crop.jpg', NULL),
(84, 'Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e Classroom of The Elite', 'youkoso-jitsuryoku-shijou-shugi-no-kyoushitsu-e-classroom-of-the-elite', 'Classroom of the Elite bercerita tentang Kiyotaka Ayanokoji, seorang siswa misterius di Kelas D Koudo Ikusei Senior High School, sebuah sekolah elit yang menerapkan sistem meritokrasi ketat di mana siswa bersaing untuk poin dan status. Kelas D dianggap terendah, namun Kiyotaka diam-diam menggunakan kecerdasan dan strategi superiornya untuk membantu teman-temannya mengatasi tantangan akademik dan sosial, menghadapi manipulasi, intrik, dan persaingan antar kelas. Cerita menekankan tema psikologi, strategi, pertumbuhan karakter, dan ketidaksetaraan dalam sistem pendidikan yang tampak adil tapi penuh permainan kekuasaan.', '', 'https://m.media-amazon.com/images/I/71oEru5zPvL._AC_UF894,1000_QL80_.jpg', NULL),
(85, 'Twilight', 'twilight', 'Twilight menceritakan kisah Isabella Bella Swan, seorang gadis yang pindah ke kota Forks yang dingin dan bertemu dengan Edward Cullen, seorang vampir misterius yang jatuh cinta padanya. Hubungan mereka rumit karena perbedaan alam mereka dan ancaman dari vampir lain, termasuk James yang memburu Bella, serta kehadiran manusia serigala Jacob Black yang juga menyukai Bella.', '', 'https://cdn0-production-images-kly.akamaized.net/d1_QXpBm1d8GJ41maGqBMb_GGiA=/800x1066/smart/filters:quality(75):strip_icc()/kly-media-production/medias/3895303/original/051293800_1641369993-The_Twilight_Saga_-_New_Moon_Portrait_3.jpg', NULL),
(86, 'Noblesse', 'noblesse', 'Noblesse bercerita tentang Cadis Etrama di Raizel, seorang Noble vampir yang tertidur selama 820 tahun dan terbangun di zaman modern. Dengan bantuan pelayannya yang setia, Frankenstein, Rai mulai menjalani kehidupan sebagai siswa di SMA Ye-Ran untuk beradaptasi dengan dunia manusia. Namun, kedamaiannya terganggu oleh organisasi rahasia bernama Union yang mengirim manusia yang dimodifikasi, memaksa Rai untuk menggunakan kekuatan dahsyatnya demi melindungi teman-temannya.', '', 'https://m.media-amazon.com/images/M/MV5BNTY0ZDMxODUtNDg3NS00NzI2LTkwMTMtOGU3YjljYjc0Yjk2XkEyXkFqcGc@._V1_.jpg', NULL),
(87, 'Avatar: The Legend of Aang', 'avatar-the-legend-of-aang', 'Avatar: The Legend of Aang adalah sinopsis dari serial animasi Avatar: The Last Airbender yang menceritakan kisah Aang, seorang anak berusia 12 tahun, yang merupakan Avatar terakhir dari kaum Pengembara Udara. Bersama dengan teman-temannya, Katara dan Sokka dari Suku Air, Aang memulai petualangan untuk menguasai keempat elemen—air, bumi, api, dan udara—demi mengakhiri Perang Seratus Tahun yang dilancarkan oleh Negara Api yang jahat.', '', 'https://upload.wikimedia.org/wikipedia/id/thumb/b/b6/Avatar_The_Last_Airbender_2024_series_poster.jpg/250px-Avatar_The_Last_Airbender_2024_series_poster.jpg', NULL),
(88, 'Napoleon (2023)', 'napoleon-2023', 'Film epik sejarah tahun 2023, Napoleon, merinci kisah kebangkitan dan kejatuhan Kaisar Prancis Napoleon Bonaparte, dengan fokus utama pada hubungan yang bergejolak dan obsesif dengan satu cinta sejatinya, Josephine de Beauharnais.  Disutradarai oleh Ridley Scott dan dibintangi oleh Joaquin Phoenix sebagai Napoleon dan Vanessa Kirby sebagai Joséphine, film ini menampilkan perjalanan hidup sang pemimpin karismatik sejak perwira militer muda hingga menjadi kaisar, dengan latar belakang Perang Revolusi Prancis dan konflik-konflik besar Eropa.', '', 'https://cdn0-production-images-kly.akamaized.net/TDCyXClQoN8oJY8KerfbSMdIUEg=/800x1066/smart/filters:quality(75):strip_icc()/kly-media-production/medias/4666940/original/074526500_1701216788-F_-UybDXsAANMAH.jpg', NULL),
(89, 'Frieren: Beyond Journeys End', 'frieren-beyond-journeys-end', 'Frieren mengikuti kisah Frieren, seorang elf penyihir yang berusia ribuan tahun dan memiliki pandangan waktu yang sangat berbeda dari manusia. Setelah ia dan kelompok pahlawannya berhasil mengalahkan Raja Iblis—sebuah perjalanan yang memakan waktu 10 tahun—Frieren menyadari bahwa bagi dirinya, waktu itu hanya sekejap.  Namun, ketika rekan-rekannya yang manusia mulai menua dan meninggal, Frieren merasakan penyesalan karena tidak pernah benar-benar memahami atau menghargai waktu yang ia habiskan bersama mereka. Untuk menebus penyesalan itu, ia memulai perjalanan baru, kali ini bukan untuk mengalahkan kejahatan besar, tetapi untuk memahami manusia, hubungan, dan makna waktu.', '', 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjrkUuNqQNJ5Uv6NIncwkrjWsdzL2V6uoV88GTZanuT0jjoK6LO1tyEecF1B2dd-A5KsEWiEKWoqn2XB2gqxpfzGuawWV1mjcMcW883BIktbJfpZS6NFjupq5EcYxTUujuhvD6f08WeFpF4EsgbQ0uvJZQLVvVHMlJEKLq8EAzHShdGeLWkGsYdGmfER_Bg/s1024/manga-frieren-hiatus.jpg', NULL),
(90, 'Soekarno (2013)', 'soekarno-2013', 'Film ini bercerita tentang perjalanan hidup Ir. Soekarno, dari masa kecil hingga ia menjadi tokoh proklamator kemerdekaan Indonesia.', '', 'https://static.mizanstore.com/d/img/book/cover/soekarno-sang-guru-bangsa.jpg', NULL),
(91, 'Habibie & Ainun (2012)', 'habibie-ainun-2012', 'Habibie & Ainun adalah film biografi-romantis Indonesia yang mengisahkan perjalanan cinta Bacharuddin Jusuf Habibie (B.J. Habibie) dan Hasri Ainun Besari sejak masa muda hingga akhir hayat Ainun.  Cerita dimulai ketika Habibie dan Ainun dipertemukan kembali setelah lama tidak bertemu sejak SMA. Ainun yang menjadi dokter dan Habibie yang sedang mendalami studi teknik di Jerman saling jatuh cinta dan menikah. Mereka kemudian hidup bersama di Jerman, tempat Habibie bekerja keras mewujudkan impiannya membangun industri pesawat untuk Indonesia.', '', 'https://upload.wikimedia.org/wikipedia/id/1/19/Buku_Habibie_Ainun.jpg', NULL),
(92, 'Shaolin Soccer (2001)', 'shaolin-soccer-2001', 'Shaolin Soccer adalah film komedi-aksi Hong Kong karya Stephen Chow yang menggabungkan seni bela diri Shaolin dengan permainan sepak bola.  Ceritanya mengikuti Sing, seorang biksu Shaolin yang ingin memperkenalkan ajaran dan kemampuan bela diri Shaolin kepada dunia modern. Suatu hari ia bertemu Fung, mantan pemain sepak bola profesional yang kariernya hancur akibat pengkhianatan.  Sing kemudian mengumpulkan saudara-saudaranya sesama murid Shaolin, masing-masing memiliki kemampuan kungfu unik. Mereka membentuk sebuah tim sepak bola yang bermain dengan teknik Shaolin yang spektakuler dan kocak—tendangan super, lompatan mustahil, dan kekuatan fisik luar biasa.  Mereka mengikuti kompetisi besar, menghadapi berbagai rintangan, termasuk tim lawan yang menggunakan cara curang dan obat-obatan untuk menang. Dengan semangat Shaolin dan kerja sama tim, mereka berjuang membuktikan bahwa kungfu bisa mengubah hidup dan membawa keajaiban di lapangan.', '', 'https://upload.wikimedia.org/wikipedia/en/3/3e/ShaolinSoccerFilmPoster.jpg', NULL),
(93, 'Kung Fu Hustle (2004)', 'kung-fu-hustle-2004', 'Kung Fu Hustle adalah film aksi-komedi garapan Stephen Chow yang memadukan kungfu klasik, slapstick, dan efek visual yang berlebihan namun menghibur.  Ceritanya berlatar di Tiongkok tahun 1940-an, ketika dunia kriminal dikuasai oleh Geng Kapak, kelompok mafia paling ditakuti. Sing, seorang pemuda miskin yang bercita-cita menjadi anggota geng tersebut, mencoba membuktikan dirinya. Namun percobaan Sing justru membawa kekacauan ke kawasan kumuh bernama Pig Sty Alley—tempat tinggal para warga biasa yang ternyata menyimpan rahasia besar.  Saat Geng Kapak mencoba menindas penghuni Pig Sty Alley, terungkap bahwa beberapa di antara warga tersebut adalah master kungfu legendaris yang hidup dalam penyamaran. Pertarungan epik pun pecah, penuh gaya bertarung unik, gerakan komedik, dan kekuatan super khas film Stephen Chow.  Dalam kekacauan itu, Sing perlahan menemukan jati dirinya. Ketika sebuah bahaya besar muncul, ia harus memutuskan apakah akan tetap menjadi penjahat kecil atau bangkit sebagai pahlawan dengan kemampuan kungfu luar biasa.', '', 'https://upload.wikimedia.org/wikipedia/id/8/87/Kung_Fu_Hustle_film.jpg', NULL),
(94, 'Kamen Rider W (Kamen Rider Double) (2009–2010)', 'kamen-rider-w-kamen-rider-double-20092010', 'Serial ini berlatar di kota Futo, sebuah kota besar yang tampak damai tetapi diam-diam dipenuhi kejahatan akibat penggunaan Gaia Memory—perangkat USB misterius yang memberi kekuatan super, namun mengubah penggunanya menjadi monster berbahaya bernama Dopant.', '', 'https://static.wikia.nocookie.net/kamenrider/images/f/fa/W_Poster.jpg', NULL),
(95, 'Animasi Puteri', 'animasi-puteri', 'Puteri adalah serial animasi fantasi yang berkisah tentang lima orang puteri kerajaan dari Kerajaan Limau. Masing-masing puteri memiliki karakter, warna khas, dan kekuatan magis berdasarkan jenis limau yang mereka wakili. Mereka tinggal bersama di istana dan sering menghadapi berbagai masalah, baik di dalam kerajaan maupun dari ancaman luar.', '', 'https://upload.wikimedia.org/wikipedia/id/2/2b/Poster_Resmi_Animasi_Puteri.png', NULL),
(96, 'KIKO (serial anak Indonesia)', 'kiko-serial-anak-indonesia', 'KIKO adalah serial animasi Indonesia yang berlatar di dunia bawah air bernama Kota Asri. Tokoh utamanya adalah Kiko, seekor ikan mas koki yang pemberani, ceria, dan selalu ingin membantu teman-temannya.', '', 'https://bukukita.com/babacms/displaybuku/109576_f.jpg', NULL),
(97, 'Zak Storm: Super Pirate', 'zak-storm-super-pirate', 'Zak Storm adalah serial animasi petualangan yang mengikuti kisah Zak Storm, seorang remaja pemberani yang tersedot ke dalam Segitiga Bermuda saat berselancar. Di sana, ia menemukan dunia misterius bernama Triangle, tempat berbagai dimensi dan makhluk unik bertemu.  Setibanya di sana, Zak memperoleh pedang ajaib bernama Calabrass, yang juga memiliki kepribadian dan kemampuan berbicara. Pedang ini memungkinkan Zak berubah menjadi pahlawan berkekuatan super dengan berbagai mode sesuai emblem yang digunakan.  Zak kemudian menjadi kapten kapal hantu canggih bernama The Chaos, dan bersama kru barunya ia berpetualang sambil mencoba menemukan jalan pulang.', '', 'https://upload.wikimedia.org/wikipedia/id/thumb/e/ef/Poster_Animasi_Zak_Storm.jpeg/250px-Poster_Animasi_Zak_Storm.jpeg', NULL),
(98, 'Captain Tsubasa', 'captain-tsubasa', 'Captain Tsubasa adalah serial manga dan anime olahraga yang mengikuti perjalanan Tsubasa Ozora, seorang anak jenius sepak bola Jepang dengan impian menjadi pemain profesional dunia.  Cerita dimulai saat Tsubasa pindah ke SD Nankatsu, di mana ia menunjukkan bakat luar biasa dalam sepak bola, terutama kemampuan dribbling, passing, dan tendangan spektakuler. Ia berteman dan bersaing dengan pemain lain yang sama-sama berbakat, termasuk Ryo Ishizaki, Kojiro Hyuga, dan Taro Misaki.  Seiring tumbuhnya Tsubasa, cerita berkembang dari level sekolah dasar ke SMP, SMA, tim nasional Jepang U-16, dan kemudian profesional, termasuk kompetisi internasional. Setiap pertandingan digambarkan dengan dramatis, menonjolkan strategi, teknik unik, dan semangat pantang menyerah.', '', 'https://upload.wikimedia.org/wikipedia/id/4/46/Captain_Tsubasa_Rise_of_New_Champions_Cover.png', NULL),
(99, 'BIMA X', 'bima-x', 'BIMA X adalah serial aksi tokusatsu yang menceritakan petualangan Ray, seorang pemuda biasa yang terpilih menjadi BIMA X, seorang pahlawan super dengan baju zirah futuristik dan kemampuan tempur luar biasa.  Ray bertarung melawan ancaman dari makhluk jahat yang disebut X-Squad dan berbagai monster yang ingin menguasai dunia. Dengan bantuan BIMA X Gear—perangkat transformasi dan senjata canggih—Ray mampu berubah menjadi BIMA X dan menggunakan berbagai kemampuan.', '', 'https://img.wattpad.com/cover/49447972-256-k230279.jpg', NULL),
(100, 'Days TV', 'days-tv', 'Ceritanya bermula dengan Tsukushi Tsukamoto, seorang siswa SMA yang pemalu, tidak atletis, dan nyaris tidak punya pengalaman sepak bola.  Suatu hari, ia bertemu Jin Kazama, pemain sepak bola jenius dan berbakat tinggi.', '', 'https://m.media-amazon.com/images/M/MV5BZGE3M2RjNGEtY2I3Yy00ZDAwLWFmZjYtZWU3ZmZhODM2MWRiXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', NULL),
(101, 'Spiderman', 'spiderman', 'Spider-Man menceritakan tentang Peter Parker, seorang remaja biasa yang tinggal di New York. Hidupnya berubah drastis ketika ia digigit oleh laba-laba radioaktif, memberinya kekuatan super seperti kelebihan kekuatan, refleks cepat, dan kemampuan menempel di dinding.', '', 'https://m.media-amazon.com/images/I/91BPTaok5JL._AC_UF1000,1000_QL80_.jpg', NULL),
(102, 'Batman', 'batman', 'Batman bercerita tentang Bruce Wayne, seorang miliarder dari Gotham City yang menyaksikan orang tuanya dibunuh saat kecil. Trauma ini membuatnya bertekad memerangi kejahatan di kotanya.  Bruce melatih dirinya dengan kemampuan fisik, ilmu detektif, teknologi canggih, dan seni bela diri, kemudian mengenakan kostum Batman, seorang pahlawan bertopeng yang bekerja di malam hari.', '', 'https://waltscomicshop.com/cdn/shop/products/batman-125-cover-a-jimenez-771605.jpg', NULL),
(103, 'Ironman', 'ironman', 'Iron Man menceritakan kisah Tony Stark, seorang miliarder jenius, playboy, dan pemilik perusahaan teknologi Stark Industries. Ia ahli dalam mekanik dan teknologi, terutama senjata canggih.  Kehidupannya berubah saat Tony disandera oleh teroris dan menyadari bahwa senjata ciptaannya digunakan untuk tujuan jahat. Untuk menyelamatkan diri dan orang lain, Tony menciptakan baju besi canggih pertama yang memberinya kekuatan super, kemampuan terbang, dan persenjataan berteknologi tinggi.  Setelah lolos dari penyanderaan, Tony memutuskan untuk menggunakan kecerdasannya untuk melawan kejahatan, bukan membuat senjata pembunuh. Dengan identitas Iron Man, ia menghadapi berbagai ancaman.', '', 'https://upload.wikimedia.org/wikipedia/id/thumb/e/ed/Iron_Man_2_poster.jpg/500px-Iron_Man_2_poster.jpg', NULL),
(104, 'Spy x Family', 'spy-x-family', 'Spy x Family adalah sinopsis tentang mata-mata ulung bernama Twilight yang harus membangun keluarga palsu—istri dan anak—untuk menjalankan misi rahasia bernama Operasi Strix demi perdamaian antara negara Ostania dan Westalis. Identitasnya menjadi Loid Forger, psikiater yang mengadopsi seorang anak bernama Anya, seorang telepat yang menyembunyikan kemampuannya. Secara bersamaan, ia menikahi Yor, seorang wanita yang ternyata adalah pembunuh bayaran profesional bernama Thorn Princess. Kehidupan keluarga palsu yang penuh rahasia, aksi, dan komedi ini menjadi inti cerita Spy x Family.', '', 'https://foto.kontan.co.id/ZOrE57ObhXITsiSBRJXZLnsm848=/smart/filters:format(webp)/2024/02/07/1453270005.jpg', NULL),
(105, 'Thor', 'thor', 'Thor menceritakan kisah Thor, dewa petir dari Asgard yang arogan, diasingkan ke Bumi oleh ayahnya, Odin, karena membangkang dan mengganggu perdamaian dengan para Raksasa Es. Di Bumi, ia kehilangan kekuatannya dan harus membuktikan dirinya layak untuk mendapatkan kembali palu Mjolnir-nya dan kembali ke Asgard untuk melawan adiknya, Loki, yang ingin merebut takhta.', '', 'https://m.media-amazon.com/images/I/91Q0rhRIwZL.jpg', NULL),
(106, 'Kamen Rider Decade', 'kamen-rider-decade', 'Kamen Rider Decade bercerita tentang seorang pemuda bernama Tsukasa Kadoya, yang memiliki kemampuan untuk berubah menjadi Kamen Rider Decade. Tsukasa memiliki misi unik: ia harus melakukan perjalanan melalui sepuluh dunia paralel yang masing-masing merupakan dunia dari Kamen Rider sebelumnya (dari Kamen Rider Kuuga hingga Kamen Rider Kiva). Tujuannya adalah untuk menyelamatkan dunia-dunia ini dari kehancuran yang disebabkan oleh kekuatan misterius bernama Kaijin dan villain khusus, serta mengungkap rahasia identitas dan takdirnya sendiri.', '', 'https://m.media-amazon.com/images/M/MV5BNzQ5MjY3MjUtZjhlYS00YjEwLWE5M2YtNTRkZDU4ZDc5ODZkXkEyXkFqcGc@._V1_.jpg', NULL),
(107, 'IPMAN', 'ipman', 'Film Ip Man menceritakan tentang kehidupan Yip Man, seorang grandmaster seni bela diri Wing Chun yang legendaris di Tiongkok, terutama selama era perang melawan invasi Jepang di tahun 1930-an. Film ini berfokus pada kemampuan seni bela diri dan keberaniannya dalam melawan penindasan, serta menjadi guru bagi banyak murid, termasuk Bruce Lee. Seri film ini mencakup periode awal hidupnya, momen-momen perjuangannya, dan pengajarannya.', '', 'https://assets.promediateknologi.id/crop/0x0:0x0/750x500/webp/photo/2021/10/13/2667007108.jpg', NULL),
(108, 'Barakamon', 'barakamon', 'Seishuu Handa, seorang seniman kaligrafi Jepang yang berusia 23 tahun. Setelah mengalami kegagalan dalam sebuah pameran seni di Tokyo, ia diasingkan ke sebuah pulau kecil bernama Goto untuk menenangkan diri dan mencari inspirasi baru. Di pulau tersebut, Handa harus beradaptasi dengan kehidupan pedesaan yang sederhana dan jauh dari kemewahan kota besar. Ia bertemu dengan berbagai karakter baru, seperti Naru Kotoishi, yang ceria dan suka bermain, serta teman-temannya yang membantu Handa menemukan kembali makna seni dan kehidupan. Melalui interaksi dengan mereka, Handa belajar banyak hal tentang dirinya sendiri dan mengembangkan gaya kaligrafinya yang lebih autentik, serta tumbuh menjadi pribadi yang lebih rendah hati dan terbuka.', '', 'https://animehunch.com/wp-content/uploads/2020/07/Barakamon-cover.jpg', NULL),
(109, 'Sakamoto desu ga?', 'sakamoto-desu-ga', 'Sakamoto desu ga? menceritakan tentang Sakamoto, seorang siswa SMA yang sempurna dalam hampir segala hal. Ia cerdas, tampan, memiliki kemampuan fisik luar biasa, dan selalu dapat mengatasi setiap masalah dengan cara yang elegan. Tingkah lakunya yang tenang dan penuh gaya membuatnya dikagumi banyak orang, namun juga memicu rasa iri dari beberapa teman sekelasnya. Meski begitu, setiap upaya menjatuhkannya selalu berakhir dengan kegagalan karena kecerdikan dan ketenangannya. Cerita ini mengikuti keseharian Sakamoto dalam menghadapi situasi kocak di sekolah, sambil menunjukkan kepribadiannya yang misterius dan selalu tak terduga.', '', 'https://meowmeowguatemala.com/wp-content/uploads/2023/03/Sakamoto-desu-ga-vol.3.webp', NULL),
(110, 'BoBoiBoy', 'boboiboy', 'BoBoiBoy adalah serial animasi asal Malaysia yang mengisahkan seorang anak sekolah bernama BoBoiBoy yang memiliki kekuatan elemental. Ia dapat membagi diri menjadi beberapa wujud dengan kemampuan berbeda seperti Elemen Petir, Tanah, Angin, dan elemen lainnya. Bersama teman-temannya seperti Yaya, Ying, Gopal, dan Fang, BoBoiBoy melindungi Bumi dari berbagai ancaman, terutama para penjahat antargalaksi yang ingin mencuri coklat kesukaan Tok Aba, kakeknya, sekaligus mengambil alih kekuatan elemental.  Cerita berlangsung dalam campuran aksi, humor, dan petualangan, menampilkan pertarungan melawan musuh seperti Adu Du, Probe, hingga musuh-musuh yang lebih kuat, sembari menonjolkan persahabatan, keberanian, dan kerja sama.  Jika ingin sinopsis yang lebih panjang, detail tiap musim, atau sinopsis filmnya (BoBoiBoy Movie 1 dan 2), beri tahu saja.', '', 'https://d26olvxuieoyaa.cloudfront.net/catalog/product/cache/1/small_image/1000x1000/9df78eab33525d08d6e5fb8d27136e95/9/7/9789671396605.jpg', NULL),
(111, 'Inuyasha', 'inuyasha', 'Inuyasha bercerita tentang Kagome Higurashi, seorang siswi modern yang secara tidak sengaja terbawa ke masa feodal Jepang setelah jatuh ke dalam sumur tua di kuil keluarganya. Di masa lalu, ia bertemu Inuyasha, sosok setengah siluman yang sedang disegel karena pernah berkonflik dengan pendeta wanita Kikyo.  Kagome ternyata membawa Shikon no Tama, sebuah permata sakti yang dapat meningkatkan kekuatan siluman. Dalam sebuah insiden, permata tersebut pecah menjadi banyak serpihan dan tersebar di seluruh penjuru negeri. Kagome dan Inuyasha kemudian bekerja sama untuk mengumpulkan kembali serpihan itu sebelum jatuh ke tangan siluman jahat, terutama Naraku, musuh utama yang licik dan berbahaya.  Sepanjang perjalanan, mereka ditemani Miroku, Sango, dan Shippo, menghadapi berbagai siluman dan rintangan sambil mengungkap masa lalu masing-masing serta hubungan rumit antara Inuyasha, Kagome, dan Kikyo.', '', 'https://d28hgpri8am2if.cloudfront.net/book_images/onix/cvr9781421532844/inuyasha-vol-5-vizbig-edition-9781421532844_hr.jpg', NULL),
(112, 'Scooby-Doo', 'scooby-doo', 'Scooby-Doo mengikuti petualangan sekelompok remaja bernama Fred, Daphne, Velma, Shaggy, dan anjing mereka Scooby-Doo dalam memecahkan berbagai misteri. Mereka tergabung dalam Mystery Inc., sebuah tim yang bepergian menggunakan mobil van bernama Mystery Machine.  Setiap kisah biasanya menghadirkan kejadian misterius yang terlihat melibatkan hantu, monster, atau makhluk supranatural. Melalui penyelidikan, petunjuk, dan berbagai kejadian lucu, mereka akhirnya mengungkap bahwa pelaku sebenarnya hampir selalu manusia yang menyamar untuk tujuan tertentu, seperti kejahatan atau penipuan.  Ciri khas Scooby-Doo adalah perpaduan komedi, teka-teki, dan aksi ringan, terutama interaksi kocak antara Shaggy dan Scooby yang sering takut namun selalu terlibat dalam pemecahan kasus secara tidak sengaja.', '', 'https://cdn.animationexplore.com/thumbs/Scooby-Doo-Legend-of-the-Phantosaur.jpg', NULL),
(113, 'Doraemon', 'doraemon', 'Doraemon mengisahkan tentang seekor robot kucing dari abad ke-22 yang dikirim ke masa kini untuk membantu seorang anak bernama Nobita Nobi. Nobita dikenal ceroboh, malas belajar, dan sering mengalami masalah di sekolah maupun kehidupan sehari-hari.  Doraemon membawa berbagai alat canggih dari kantong empat dimensinya, seperti Pintu Kemana Saja, Baling-baling Bambu, dan Mesin Waktu. Dengan alat-alat tersebut, ia berusaha menolong Nobita agar kehidupannya lebih baik dan masa depannya tidak berakhir buruk. Namun, penggunaan alat itu sering menimbulkan kekacauan baru karena kecerobohan Nobita sendiri.  Cerita berfokus pada persahabatan, petualangan, serta nilai tentang usaha, tanggung jawab, dan kebaikan hati, dengan latar kehidupan sederhana anak-anak sekolah di Jepang.', '', 'https://i.pinimg.com/736x/b8/88/f5/b888f5861fadde26ea988d65f1493ea9.jpg', NULL),
(114, 'Bima S', 'bima-s', 'Bima S adalah serial animasi Indonesia yang mengangkat kisah petualangan Satria, seorang remaja terpilih yang mendapat kekuatan dari Red Power Stone. Dengan kekuatan tersebut, ia dapat berubah menjadi Bima S, seorang pejuang futuristik yang memiliki kemampuan super dan teknologi canggih.  Satria diberi misi untuk melindungi Bumi dari ancaman kekuatan jahat, terutama Varga dan para makhluk interdimensional lain yang ingin menguasai sumber energi powerful bernama Energi Primordial. Bersama para sahabatnya, seperti Aurora, Karen, dan karakter pendukung lain, Bima S menghadapi berbagai musuh yang semakin kuat sambil mengungkap misteri asal kekuatan dan ancaman yang lebih besar di balik konflik antardimensi.  Serial ini menonjolkan aksi, teknologi, dan nilai keberanian serta persahabatan, dengan gaya animasi 3D dan dunia futuristik yang menjadi ciri khas waralaba Satria Garuda Bima.', '', 'https://m.media-amazon.com/images/M/MV5BNDlkMzQ3NTktNjRhMS00MjQ2LTg4MGYtMmNiZWQ5MzhhYmIxXkEyXkFqcGc@._V1_.jpg', NULL),
(115, 'Ultraman Mebius', 'ultraman-mebius', 'Ultraman Mebius mengikuti kisah Mirai Hibino, seorang anggota muda Ultras yang dikirim dari Nebula M78 ke Bumi untuk melindungi umat manusia dari ancaman monster dan alien jahat. Ia menyamar sebagai manusia bernama Mirai dan bergabung dengan pasukan pertahanan GUYS (Guardians of Utility Something), sebuah tim khusus yang menangani serangan monster.  Mirai berjuang membuktikan diri sebagai Ultraman muda yang penuh semangat, sambil belajar memahami manusia dan membangun hubungan kuat dengan anggota GUYS seperti Ryu, Konomi, George, Marina, dan Teppei. Seiring berjalannya waktu, Mebius menghadapi musuh-musuh kuat, termasuk anggota aliansi monster dan para alien berbahaya yang ingin mengambil alih Bumi.  Serial ini juga menampilkan kemunculan para Ultraman pendahulu seperti Ultraman, Ultraseven, Taro, Ace, dan Zoffy yang memberi dukungan dan menjadi mentor bagi Mebius. Melalui pertarungan dan perjalanan emosionalnya, Ultraman Mebius tumbuh menjadi salah satu pelindung Bumi yang paling dihormati.', '', 'https://image.tmdb.org/t/p/original/v19lPIh9qGwEc6OHVJdpwlaxOyI.jpg', NULL),
(116, 'Ultraman Taro', 'ultraman-taro', 'Ultraman Taro bercerita tentang Kotaro Higashi, seorang pemuda pemberani yang bergabung dengan pasukan pertahanan ZAT (Zariba of All Territory). Dalam salah satu misi, Kotaro terluka parah akibat serangan monster. Untuk menyelamatkan hidupnya dan memberi Bumi pelindung baru, Pasukan Ultra dari Nebula M78 menyatukan jiwa Kotaro dengan Ultraman Taro, anggota muda Keluarga Ultra.  Sebagai Ultraman Taro, Kotaro melawan berbagai monster dan alien yang mengancam keselamatan umat manusia. Ia juga dibimbing oleh para Ultra senior seperti Taro’s Father, Mother of Ultra, Ultraman Ace, Ultraman Tiga, dan anggota Ultra lainnya yang kerap muncul sebagai mentor.  Serial ini menonjolkan tema keberanian, pengorbanan, serta hubungan Taro dengan Keluarga Ultra. Ceritanya menggabungkan aksi pertarungan, drama kemanusiaan, dan unsur fantasi khas dunia Ultra.', '', 'https://www.boomerangshop.com/web/files/product/202101/01669722-20210120153921-0.jpg', NULL),
(117, 'Ultraman Geed', 'ultraman-geed', 'Ultraman Geed mengisahkan Riku Asakura, seorang pemuda yang mengetahui bahwa ia adalah keturunan dari Ultraman Belial, Ultra jahat yang pernah mengancam alam semesta. Meski mewarisi garis keturunan Belial, Riku memilih jalan berbeda dan bertekad melindungi Bumi. Dengan menggunakan Geed Riser dan Ultra Capsule, ia berubah menjadi Ultraman Geed.  Riku bergabung dengan AIB (Alien Investigation Bureau) serta bekerja sama dengan para sekutu seperti Laiha, Moa, Reito, dan Pega. Mereka menghadapi berbagai ancaman, termasuk monster-monster yang dilepas oleh Kei Fukuide, manusia yang menjadi perpanjangan tangan Belial.  Seiring perjalanan, Riku berusaha memahami identitasnya, melawan bayang-bayang Belial, serta membuktikan bahwa takdir tidak menentukan pilihan seseorang. Konflik mencapai puncaknya ketika Geed harus menghadapi Belial secara langsung untuk menjaga masa depan umat manusia dan dunia Ultra.', '', 'https://images.static-bluray.com/products/20/90652_1_large.jpg', NULL),
(118, 'Ultraseven', 'ultraseven', 'Ultraseven menceritakan tentang seorang Ultra yang datang ke Bumi untuk mengamati kehidupan manusia di tengah meningkatnya ancaman dari monster dan alien. Untuk berbaur, ia mengambil wujud seorang manusia bernama Dan Moroboshi setelah menyelamatkan seorang pendaki di pegunungan.  Dan kemudian bergabung dengan pasukan pertahanan khusus Ultra Guard, bagian dari organisasi TDF (Terrestrial Defense Force), yang bertugas melindungi Bumi dari invasi makhluk luar angkasa. Saat situasi genting, Dan berubah menjadi Ultraseven menggunakan Ultra Eye, sebuah alat yang memicu transformasi.  Serial ini menonjolkan tema kemanusiaan, pengorbanan, dan konflik moral, karena banyak musuh bukan sekadar monster, tetapi alien dengan motif dan latar belakang yang kompleks. Ultraseven dikenal sebagai pahlawan yang tegas namun penuh empati, sering menghadapi dilema antara tugas sebagai pelindung dan rasa hormatnya terhadap kehidupan.', '', 'https://images-na.ssl-images-amazon.com/images/I/81hpjoXE9UL._AC_SL1500_.jpg', NULL),
(119, 'Ultraman Zero', 'ultraman-zero', 'Ultraman Zero adalah putra Ultraseven dan salah satu Ultra Warrior terkuat dari Nebula M78. Sejak muda, Zero memiliki potensi besar tetapi bersifat impulsif dan keras kepala. Karena sikapnya, ia sempat diasingkan untuk berlatih di bawah bimbingan Ultraman Leo agar dapat menguasai kekuatan dan kedisiplinan seorang prajurit Ultra.  Setelah menguasai kemampuan tempurnya, Zero kembali sebagai pahlawan yang melindungi berbagai dunia di multiverse. Ia menghadapi ancaman besar seperti Ultraman Belial, Ultra yang terjatuh ke sisi jahat dan menjadi musuh utamanya. Konflik dengan Belial menjadi pusat perjalanan Zero dalam banyak cerita, dari pertempuran di Planet Ultra hingga pencampuran dimensi di berbagai film dan miniseri.  Zero kemudian bekerja sama dengan para pahlawan seperti Ultraman Dyna, Ultraman Cosmos, serta duo alien Jean-Bot dan Glenfire dalam kelompok Ultimate Force Zero. Dengan keberanian, kegigihan, dan rasa tanggung jawab yang semakin matang, Zero tumbuh menjadi simbol harapan bagi banyak dunia.', '', 'https://musicart.xboxlive.com/7/8fae5100-0000-0000-0000-000000000002/504/image.jpg', NULL),
(120, 'Ultraman Orb', 'ultraman-orb', 'Ultraman Orb mengikuti kisah Gai Kurenai, seorang pengembara yang dapat berubah menjadi Ultraman Orb menggunakan Fusion Card, kartu yang menggabungkan kekuatan dua Ultraman pendahulu untuk menciptakan berbagai bentuk, seperti Spacium Zeperion atau Burnmite. Gai hidup berpindah-pindah sambil menjaga Bumi dari ancaman monster dan makhluk gelap.  Musuh utamanya adalah Jugglus Juggler, mantan sahabat yang kini menjadi lawan. Jugglus berusaha membangkitkan monster-monster berbahaya dan mendorong Gai ke batas kemampuan, sambil memanfaatkan masa lalu kelam di antara mereka. Gai kemudian bergabung dengan tim penyelidikan paranormal SSP (Something Search People) yang terdiri dari Naomi, Jetta, dan Shin. Bersama kelompok kecil ini, ia menghadapi berbagai ancaman sambil perlahan mengungkap hubungan rumit antara dirinya, Juggler, dan kekuatan Orb.  Cerita Ultraman Orb menonjolkan tema penebusan, konflik masa lalu, serta perjalanan seorang pahlawan yang terus berjuang meskipun dibayangi kegagalan sebelumnya. Serial ini menggabungkan aksi, misteri, dan dinamika karakter yang kuat.', '', 'https://www.dvdplanetstore.pk/wp-content/uploads/2017/12/b4zLXKLctaoEfuja48QxwnqdF07.jpg', NULL),
(121, 'Kamen Rider Build', 'kamen-rider-build', 'Kamen Rider Build mengisahkan Sento Kiryu, seorang ilmuwan jenius yang kehilangan ingatannya. Ia menemukan dirinya terlibat dalam konflik besar setelah munculnya Skywall Disaster, dinding raksasa yang membagi Jepang menjadi tiga wilayah: Touto, Hokuto, dan Seito. Bencana itu dipicu oleh Pandora Box, artefak misterius yang ditemukan dari Mars.  Sento menjadi Kamen Rider Build menggunakan Build Driver dan Full Bottle yang memadukan dua elemen berbeda, menghasilkan berbagai bentuk seperti RabbitTank atau GorillaDiamond. Tujuan utamanya adalah mengungkap kebenaran tentang ingatan yang hilang, penelitian rahasia, serta asal mula kekuatan yang ia gunakan.  Ia bekerja sama dengan Ryuga Banjou, mantan petinju yang dijebak atas kasus pembunuhan dan kemudian menjadi Kamen Rider Cross-Z. Bersama, mereka menghadapi organisasi jahat Faust, eksperimen berbahaya, serta meningkatnya perang antarwilayah akibat manipulasi politik dan ambisi kekuatan Pandora Box.  Perjalanan Sento perlahan mengungkap identitas asli dirinya, hubungan dengan musuh-musuh utama, serta pilihan moral yang besar tentang pengorbanan, persahabatan, dan masa depan dunia.', '', 'https://www.imfdb.org/images/thumb/8/88/KRB_BRC1_cover.jpg/800px-KRB_BRC1_cover.jpg', NULL),
(122, 'Ultraman Max', 'ultraman-max', 'Ultraman Max mengikuti kisah Kaito Touma, anggota tim pertahanan DASH (Defense Action Squad Heroes) yang bertugas menghadapi kemunculan monster dan ancaman luar angkasa di Bumi. Dalam suatu insiden berbahaya, Kaito dipilih oleh Ultraman Max dari Nebula M78 untuk menjadi inangnya, sehingga ia dapat berubah menjadi Max untuk melindungi umat manusia.  Ultraman Max dikenal sebagai Ultra yang cepat, kuat, dan berpengalaman. Bersama DASH, ia menghadapi berbagai monster klasik maupun baru, serta ancaman dari alien yang ingin mengambil alih Bumi. Hubungan antara Kaito dan Max ditampilkan lebih dekat dan komunikatif dibanding seri lain, menggambarkan kolaborasi nyata antara manusia dan Ultra.  Serial ini menonjolkan tema keberanian, kerja tim, dan kemanusiaan, sambil menghadirkan nuansa nostalgia karena banyak episode ditangani oleh sutradara veteran dari seri Ultraman Showa.', '', 'https://image.tmdb.org/t/p/original/18bp74xrGnx71aLEWHlZXBO9jlP.jpg', NULL),
(123, 'Ultraman Hikari', 'ultraman-hikari', 'Ultraman Hikari, yang sebelumnya dikenal sebagai Hunter Knight Tsurugi, adalah Ultra dari Nebula M78 yang awalnya merupakan ilmuwan. Ia meninggalkan perannya sebagai ilmuwan setelah planet Arb, dunia yang ia lindungi, dihancurkan oleh monster Bogar. Diliputi rasa bersalah dan penyesalan, ia mengambil wujud gelap Tsurugi dan menjelma menjadi ksatria pemburu yang kejam, hanya berfokus pada balas dendam.  Dalam perjalanannya, Tsurugi bertemu Ultraman Mebius dan para Ultra lainnya. Melalui interaksi dan pertarungan bersama, ia mulai memahami kembali nilai harapan, keberanian, dan kerja sama. Setelah melepaskan dendamnya, ia kembali ke wujud aslinya sebagai Ultraman Hikari. Sejak itu, Hikari berperan sebagai mentor dan pendukung bagi para Ultra muda, terutama Mebius.  Hikari dikenal karena kecerdasannya sebagai ilmuwan dan kekuatan bertarungnya sebagai ksatria. Ia sering menciptakan senjata, teknologi Ultra, dan memberikan strategi dalam menghadapi ancaman terhadap Planet Ultra maupun Bumi.', '', 'https://static.wikia.nocookie.net/ultra/images/3/35/Hikari_data.png', NULL),
(124, 'Merah Putih (2009)', 'merah-putih-2009', 'Merah Putih adalah film berlatar masa Revolusi Kemerdekaan Indonesia tahun 1947. Cerita berfokus pada sekelompok pemuda dari latar belakang berbeda yang dipersatukan dalam satu pasukan setelah menjalani latihan militer untuk melawan penjajah Belanda dalam Agresi Militer I.  Tokoh-tokohnya termasuk Amir, seorang intelektual; Tomas, pemuda blasteran yang keras kepala; Dayan, petani yang sederhana namun setia; dan Marius, anak seorang bangsawan. Meski sering berbeda pendapat, mereka terpaksa bekerja sama setelah pasukan tempat mereka berlatih diserang dan banyak rekannya gugur. Mereka kemudian bergabung dalam perjuangan gerilya di hutan bersama kapten mereka yang masih hidup.  Sepanjang perjalanan, kelompok ini menghadapi tekanan perang, kehilangan, dan pergulatan batin. Perbedaan karakter dan status sosial perlahan melebur ketika mereka menyadari bahwa tujuan mereka sama: mempertahankan kemerdekaan Indonesia. Persahabatan, pengorbanan, dan tekad menjadi inti dari perjalanan mereka.', '', 'https://www.mafab.hu/static/profiles/2014/293/06/29871_40.jpg', NULL),
(125, 'Power Rangers', 'power-rangers', 'Power Rangers adalah serial aksi yang mengikuti sekelompok remaja terpilih yang diberi kekuatan khusus untuk melindungi Bumi dari ancaman monster, alien, atau pasukan jahat dari berbagai dimensi. Setiap Ranger memiliki warna khas, senjata, dan kemampuan tempur yang diperoleh melalui Morpher atau perangkat transformasi lain.  Selain kekuatan individu, para Ranger dapat mengendalikan Zord, robot raksasa berbentuk hewan, kendaraan, atau makhluk mitologis. Zord-Zord tersebut dapat bergabung menjadi Megazord, robot besar yang digunakan untuk menghadapi musuh berukuran raksasa.  Cerita tiap musim biasanya dimulai ketika ancaman baru muncul. Mentor seperti Zordon, Gosei, atau sosok lain memilih para Ranger dan membimbing mereka dalam memahami tanggung jawabnya. Para Ranger tidak hanya bertarung, tetapi juga menghadapi konflik pribadi, persahabatan, dan tantangan hidup remaja.  Intinya, Power Rangers menekankan kerja sama tim, keberanian, dan tekad untuk melindungi dunia dari kejahatan.', '', 'https://majorspoilers.com/wp-content/uploads/2022/10/Mighty-Morphin-Power-Rangers-101-Cover-scaled.jpg', NULL),
(126, 'Up (2009)', 'up-2009', 'Up mengisahkan Carl Fredricksen, seorang pria tua yang hidup sendiri setelah kehilangan istrinya, Ellie. Sejak kecil, Carl dan Ellie bermimpi pergi ke Paradise Falls, tempat indah di Amerika Selatan yang selalu mereka kagumi. Setelah Ellie meninggal, Carl tetap menyimpan janji untuk mewujudkan impian itu.  Ketika rumahnya terancam digusur, Carl mengikat ribuan balon helium ke rumahnya sehingga rumah itu terangkat dan terbang menuju Paradise Falls. Tanpa ia sadari, seorang anak Pramuka bernama Russell ikut terbawa dalam perjalanan tersebut.  Di perjalanan, mereka bertemu seekor burung langka bernama Kevin dan anjing yang bisa bicara bernama Dug. Carl dan Russell akhirnya harus berhadapan dengan Charles Muntz, penjelajah legendaris yang ternyata terobsesi menangkap Kevin.  Melalui petualangan ini, Carl menyadari bahwa kehidupan bersama Ellie sudah merupakan petualangan terbesar dalam hidupnya. Ia belajar membuka diri kembali, menghargai kenangan masa lalu, dan memberi ruang bagi hubungan baru.', '', 'https://alchetron.com/cdn/Up-2009-film-images-c5010920-e2ba-42d9-b683-0f8bf6b837e.jpg', NULL);
INSERT INTO `komik` (`id`, `judul`, `slug`, `penulis`, `penerbit`, `gambar`, `tahun_terbit`) VALUES
(127, 'The Reincarnated Assassin Is a Genius Swordmaster', 'the-reincarnated-assassin-is-a-genius-swordmaster', 'Raon adalah seorang assassin paling loyal milik House Robert. Namun kesetiaannya berakhir tragis ketika ia dikhianati dan dibunuh oleh Derus Robert, pemimpin yang selama ini ia layani. Kematian itu tidak mengakhiri perjalanannya. Melalui kejadian tak terduga, Raon bereinkarnasi sebagai cucu Glenn Zieghart, pemimpin legendaris sekaligus Raja Penghancur dari House Zieghart, salah satu keluarga pedang terkuat di dunia.  Dalam kehidupan barunya sebagai Raon Zieghart, ia membawa dua beban besar: Flame Link, kekuatan teknik mematikan dari kehidupan lamanya, dan Curse of Bitter Frost, kutukan dingin yang melemahkannya sejak lahir. Selain itu, tubuh barunya juga dihuni oleh sosok iblis bernama Wrath, salah satu Raja Iblis yang terus berusaha merebut kendali atas dirinya.  Meskipun terlahir lemah, Raon perlahan membangun kekuatannya dari dasar. Ia berlatih keras di lingkungan keluarga bangsawan yang keras dan ambisius, sambil menyembunyikan masa lalu gelapnya sebagai assassin. Tujuannya jelas: membalas dendam kepada Derus Robert dan menghancurkan para pengkhianat yang menghancurkan hidupnya dahulu.  Manhwa ini menonjolkan tema balas dendam, pertumbuhan kekuatan, intrik keluarga bangsawan, dan perjuangan Raon melawan kutukan, ambisi, serta tekanan dari entitas iblis di dalam dirinya.', '', 'https://k06.mbqgu.org/thumb/W600/ampi/b81/b811b4979377eec949df8d3986a1c18973aaab8a_400_600_69578.jpeg', NULL),
(128, 'Majutsushi to Yajuu', 'majutsushi-to-yajuu', 'Cerita mengikuti perjalanan dua tokoh utama: Guideau, seorang gadis misterius yang terkutuk menjadi berwujud seperti binatang buas, dan Ashaf, penyihir tenang yang selalu membawa peti mati hitam di punggungnya. Keduanya adalah anggota Order of Magical Resonance, organisasi yang menangani kasus-kasus berbahaya terkait sihir, iblis, dan kutukan.  Guideau sedang mencari penyihir kuat yang mengutuknya, dengan tujuan membalas dendam dan mematahkan kutukannya. Sementara Ashaf memiliki misi lebih kompleks yang terkait dengan penyihir tersebut serta konflik besar di dunia para magus. Dalam perjalanan, mereka terlibat dalam serangkaian kasus gelap: penyihir pemberontak, iblis terlarang, eksperimen manusia, hingga perang antar faksi sihir.  Dinamika utama cerita terletak pada hubungan kontras keduanya: Guideau yang impulsif dan haus balas dendam, sementara Ashaf bersikap tenang, penuh strategi, dan menyimpan banyak rahasia. Seiring waktu, berbagai misteri tentang kutukan Guideau, isi peti mati Ashaf, dan organisasi yang menaungi mereka perlahan terungkap.', '', 'https://www.intoxianime.com/wp-content/uploads/2023/07/F06li1ZaAAM455p.jpg', NULL),
(129, 'Juni Taisen: Zodiac War', 'juni-taisen-zodiac-war', 'Setiap dua belas tahun sekali, digelar Juni Taisen, sebuah turnamen mematikan yang mempertemukan dua belas pembunuh profesional yang masing-masing mewakili lambang zodiak Tiongkok. Mereka memiliki kemampuan khusus, gaya bertarung unik, serta latar belakang tragis yang berbeda-beda. Aturan turnamen sederhana: hanya satu yang boleh hidup. Pemenang berhak mengabulkan satu keinginan apa pun, tanpa batas.  Dalam perang kali ini, kontestan memasukkan (permata beracun) ke tubuh masing-masing, membuat batas waktu bertahan hidup menjadi lebih pendek. Pertempuran terjadi di seluruh kota yang sudah dikosongkan, menampilkan pengkhianatan, aliansi sesaat, dan strategi kejam demi bertahan hidup.  Tokoh yang paling menonjol adalah Usagi (Kelinci) yang gila dan ahli necromancy, lalu Nezumi (Tikus) yang tampak lemah namun memiliki kecerdikan luar biasa. Perlahan, satu per satu peserta mati dengan cara tragis. Para petarung seperti OX, Monkey, Tiger, dan Snake masing-masing memperlihatkan kekuatan serta konflik moral mereka hingga tersisa sedikit saja.  Ending / Penutup Pemenang Juni Taisen adalah Nezumi (Tikus). Kemampuan aslinya adalah (Hundred Paths of Nezumi), yang membuatnya dapat mengalami dan memilih satu dari seratus kemungkinan masa depan. Dengan kekuatan itulah ia bertahan dan memenangkan pertarungan.  Sebagai pemenang, Nezumi berhak mengajukan satu permintaan apa pun. Namun setelah melihat berbagai kemungkinan masa depan, apa pun yang ia pilih selalu berakhir dengan konsekuensi buruk. Semua pilihan terasa salah. Akhirnya, Nezumi justru memilih (Aku ingin melupakan seluruh Juni Taisen ini.) Permintaan itu dikabulkan. Ia kembali menjalani hidup normal, tanpa ingatan tentang pembantaian ataupun kekuatan yang ia gunakan. Turnamen berakhir, namun siklus dua belas tahun dipastikan akan terus berlanjut di masa depan.', '', 'https://d28hgpri8am2if.cloudfront.net/book_images/onix/cvr9781974705634/juni-taisen-zodiac-war-manga-vol-4-9781974705634_xlg-back.jpg', NULL),
(130, 'Tokyo Ghoul', 'tokyo-ghoul', 'Di kota Tokyo, manusia hidup berdampingan dengan makhluk pemakan daging manusia yang disebut Ghoul. Mereka tampak seperti manusia biasa, namun memiliki kekuatan fisik jauh di atas manusia, serta organ khusus bernama kagune untuk bertarung.  Kisah berpusat pada Ken Kaneki, seorang mahasiswa yang awalnya hidup normal. Segalanya berubah ketika ia mengalami kecelakaan setelah kencan dengan seorang perempuan bernama Rize, yang ternyata adalah Ghoul pemangsa. Untuk menyelamatkan nyawanya, dokter melakukan transplantasi organ Rize ke tubuh Kaneki. Operasi itu membuatnya menjadi setengah Ghoul.  Kaneki kini terjebak di antara dua dunia: tidak bisa hidup sebagai manusia biasa karena harus memakan daging manusia, tetapi juga tidak diterima sepenuhnya oleh para Ghoul. Ia akhirnya diselamatkan oleh kelompok Ghoul ramah bernama Anteiku, tempat ia belajar mengendalikan identitas barunya.  Perlahan, konflik antara manusia dan Ghoul makin meningkat. Organisasi anti-Ghoul CCG terus memburu para Ghoul, sementara kelompok Ghoul radikal seperti Aogiri Tree menebar kekacauan. Kaneki berada di tengah perang identitas, kekerasan, dan dilema moral. Ia berusaha melindungi orang-orang yang ia sayangi sambil memahami apa arti menjadi manusia.', '', 'https://d28hgpri8am2if.cloudfront.net/book_images/onix/cvr9781421580364/tokyo-ghoul-vol-1-9781421580364_hr.jpg', NULL),
(131, 'King Kong', 'king-kong', 'Sebuah ekspedisi film berlayar menuju pulau terpencil bernama Skull Island, dipimpin oleh seorang sutradara ambisius. Di pulau itu, mereka menemukan makhluk raksasa legendaris: Kong, seekor gorila besar yang ditakuti penduduk setempat.  Kong kemudian jatuh hati pada seorang perempuan muda dalam rombongan tersebut (biasanya bernama Ann Darrow atau tokoh sejenis tergantung versi film). Saat kru ekspedisi mencoba menyelamatkannya, mereka justru membawa Kong kembali ke New York untuk dipamerkan sebagai tontonan.  Namun Kong lolos, mengamuk di kota, dan mengejar perempuan yang ia lindungi. Klimaks tragis terjadi ketika Kong memanjat Empire State Building, bertarung melawan pesawat-pesawat yang menyerangnya. Pada akhirnya Kong tewas, meninggalkan kesan bahwa keindahanlah yang membunuh sang raksasa.', '', 'https://upload.wikimedia.org/wikipedia/id/6/6a/Kingkong_bigfinal1.jpg', NULL),
(132, 'Jumanji', 'jumanji', 'Jumanji adalah kisah tentang sebuah permainan misterius yang memiliki kekuatan magis untuk membawa dunia di dalamnya ke dunia nyata — atau menarik pemain masuk ke dalam permainannya.  Cerita dimulai ketika beberapa tokoh menemukan papan permainan (atau video game, dalam versi modern). Ketika mereka mulai bermain, mereka menyadari bahwa setiap giliran memunculkan bahaya nyata, seperti binatang buas, perangkap hutan, hingga tantangan hidup-mati yang harus mereka selesaikan.  Para pemain harus bekerja sama menyelesaikan semua level permainan sampai giliran terakhir. Hanya dengan menuntaskan permainan dan mengucapkan kata Jumanji, semua kekacauan akan kembali normal, dan para pemain dapat kembali ke kehidupan mereka.  Film ini memadukan petualangan, fantasi, dan humor, sekaligus menekankan nilai persahabatan, keberanian, dan kerja sama.', '', 'https://upload.wikimedia.org/wikipedia/id/1/13/Jumanji_Welcome_to_the_Jungle_Poster.jpg', NULL),
(133, 'Godzilla', 'godzilla', 'Godzilla adalah kisah tentang munculnya seekor monster raksasa dari laut dalam akibat gangguan aktivitas manusia—sering dikaitkan dengan uji coba nuklir, pencemaran lingkungan, atau fenomena alam yang tak terkendali. Makhluk ini berbentuk seperti reptil prasejarah yang sangat besar, memiliki kekuatan luar biasa, termasuk napas atom (atomic breath) yang menghancurkan apa saja di hadapannya.  Ketika Godzilla muncul ke permukaan, kota-kota besar menjadi medan kekacauan. Pemerintah, ilmuwan, dan militer berusaha mencari cara untuk menghentikannya, tetapi sering kali menyadari bahwa kekuatan manusia tak sebanding dengan makhluk purba tersebut.  Namun, Godzilla tidak selalu menjadi musuh. Dalam banyak versi, ia menjadi pelindung bumi, melawan monster-monster lain (Kaijuu) yang lebih berbahaya, seperti King Ghidorah, Mothra, atau Rodan. Konflik biasanya berpuncak pada pertarungan kolosal antar Kaijuu yang menentukan nasib umat manusia.  Akhir cerita sering menggambarkan Godzilla kembali ke laut—sebagai simbol bahwa alam akan selalu memiliki kekuatan lebih besar daripada manusia.', '', 'https://upload.wikimedia.org/wikipedia/id/9/9a/Godzilla_%E2%80%93_King_of_the_Monsters_%282019%29_poster.png', NULL),
(134, 'Battle: Los Angeles (2011)', 'battle-los-angeles-2011', 'Ketika objek-objek misterius jatuh dari langit dan mendarat di berbagai kota besar dunia, umat manusia segera menyadari bahwa itu bukan meteor—melainkan pasukan alien yang datang untuk melakukan invasi skala penuh. Los Angeles menjadi salah satu titik serangan terbesar.  Sersan Marinir AS Michael Nantz, yang baru saja berniat pensiun, ditugaskan kembali untuk memimpin sekelompok prajurit muda dalam misi berbahaya: menyelamatkan warga sipil yang terjebak di zona perang dan mengevakuasi mereka sebelum serangan udara besar dilancarkan.  Di tengah kehancuran total kota, tim Marinir berjuang melawan alien bersenjata canggih yang tampaknya tak terkalahkan. Pertempuran intens pun berlangsung dari jalanan, gedung-gedung, hingga pusat komando alien yang menjadi kunci invasi.  Nantz dan timnya harus berpacu melawan waktu—bukan hanya untuk bertahan hidup, tetapi juga untuk menemukan cara menghentikan invasi dan memberi harapan bagi umat manusia.', '', 'https://upload.wikimedia.org/wikipedia/en/thumb/f/ff/Battleoflosangelesdvd.jpg/250px-Battleoflosangelesdvd.jpg', NULL),
(135, 'Train to Busan (2016)', 'train-to-busan-2016', 'Seok-woo, seorang manajer investasi yang sibuk dan kurang dekat dengan putrinya, Soo-an, memutuskan untuk mengantarnya naik kereta KTX dari Seoul menuju Busan untuk menemui ibunya sebagai hadiah ulang tahun.  Namun perjalanan mereka berubah menjadi mimpi buruk ketika wabah zombie tiba-tiba merebak di seluruh Korea Selatan. Seorang penumpang yang terinfeksi berhasil naik ke kereta, dan dalam hitungan menit virus mematikan tersebut menyebar dengan cepat dari gerbong ke gerbong.  Para penumpang yang tersisa harus berjuang melawan zombie yang lincah dan agresif, sambil menghadapi kepanikan, pengorbanan, dan sifat asli manusia yang muncul di tengah krisis. Seok-woo perlahan berubah menjadi ayah yang lebih peduli, terutama saat melindungi Soo-an dari bahaya yang semakin mendekat.  Sementara kereta terus melaju tanpa kepastian, para oc survivor berusaha mencapai Busan—satu-satunya kota yang dikabarkan masih aman. Namun tidak semua perjalanan menuju keselamatan berakhir bahagia.  Film ini terkenal karena ketegangan nonstop, drama emosional, dan pesan kemanusiaan yang kuat.', '', 'https://upload.wikimedia.org/wikipedia/id/9/95/Train_to_Busan.jpg', NULL),
(136, 'Knowing (2009)', 'knowing-2009', 'Pada tahun 1959, sekelompok murid sekolah dasar membuat kapsul waktu berisi gambar-gambar mereka yang akan dibuka 50 tahun kemudian. Salah satu murid, Lucinda Embry, malah mengisi kertasnya dengan deretan angka acak yang aneh dan penuh misteri.  Lima puluh tahun kemudian, kertas itu ditemukan oleh John Koestler, seorang profesor astrofisika yang sedang berjuang mengatasi duka setelah kehilangan istrinya. Saat ia memperhatikan deretan angka itu, John menyadari bahwa pola tersebut ternyata adalah prediksi akurat tentang berbagai bencana besar yang telah terjadi—tanggal, lokasi, dan jumlah korban—semuanya benar.  Lebih mengejutkan lagi, masih ada beberapa peristiwa yang belum terjadi, termasuk tragedi besar yang tampaknya berskala global. Ketika John mencoba memperingatkan orang lain, ia makin dalam terjerat pada misteri yang melibatkan angka-angka, bisikan gaib, dan keberadaan makhluk misterius yang muncul di sekitar putranya, Caleb.  John akhirnya menemukan bahwa angka terakhir bukan hanya bencana biasa, melainkan akhir dunia yang tak dapat dihindari. Dalam upayanya menyelamatkan Caleb, ia menemukan kebenaran tentang apa yang sebenarnya sedang terjadi dan peran anak-anak yang “dipilih”. Film ini menggabungkan unsur thriller, sci-fi, misteri, dan elemen apokaliptik, dengan fokus pada nasib manusia dan takdir yang tak dapat diubah.', '', 'https://upload.wikimedia.org/wikipedia/id/0/08/Knowingposter08.jpg', NULL),
(137, 'Ultraman Nexus', 'ultraman-nexus', 'Cerita berlangsung dalam dunia modern yang dibayangi oleh kemunculan Space Beast, monster misterius yang menyerang manusia secara brutal. Untuk melindungi masyarakat, pemerintah membentuk organisasi rahasia bernama TLT (Terrestrial Liberation Trust), lengkap dengan unit tempurnya, Night Raiders, yang bertugas melawan para Beast.  Di tengah kekacauan ini, muncul sosok raksasa cahaya baru: Ultraman Nexus, yang wujudnya berubah-ubah sesuai Dunamist—manusia terpilih yang menjadi inangnya.', '', 'https://cdromance.org/wp-content/uploads/2016/09/un-1.jpg', NULL),
(138, 'Ultraman Ginga', 'ultraman-ginga', 'Ultraman Ginga menceritakan tentang dunia di mana semua Ultraman dan monster telah berubah menjadi figur mini bernama Spark Dolls akibat sebuah peristiwa kosmis misterius. Seorang remaja bernama Hikaru Raido kembali ke kampung halamannya dan menemukan Ginga Spark, alat yang memungkinkannya berubah menjadi Ultraman Ginga serta menghidupkan Spark Dolls menjadi makhluk raksasa.  Namun, muncul pula kekuatan gelap yang mempengaruhi sebagian orang untuk menggunakan Spark Dolls secara jahat, termasuk kehadiran musuh kuat yang berada di balik perubahan seluruh Ultraman dan monster tersebut. Hikaru bersama teman-temannya harus melindungi bumi sekaligus mengungkap penyebab tragedi besar itu.  Cerita berfokus pada pertumbuhan Hikaru, pertempuran melawan musuh yang memanfaatkan Spark Dolls, serta misteri asal-usul Ginga dan kekuatan kosmis yang mengancam alam semesta.', '', 'https://tsuburaya-prod.com/wp-content/uploads/2021/11/P2013_%E3%82%AE%E3%83%B3%E3%82%AC_01B.jpg', NULL),
(139, 'Ultraman Jack (Return of Ultraman, 1971)', 'ultraman-jack-return-of-ultraman-1971', 'Ultraman Jack berkisah tentang Hideki Go, seorang pemuda yang tewas ketika mencoba menyelamatkan seorang anak dan anjingnya dari kecelakaan besar. Pada saat kritis itu, ia diselamatkan oleh makhluk raksasa dari Nebula M78 yang kemudian menyatu dengannya. Makhluk itu kelak dikenal sebagai Ultraman Jack.  Setelah hidup kembali, Hideki direkrut oleh MAT (Monster Attack Team), tim pertahanan yang bertugas menghadapi monster dan ancaman luar angkasa. Dengan kekuatan Ultraman Jack yang dapat ia akses ketika situasi genting, Hideki berjuang melindungi bumi dari berbagai serangan monster dan alien yang terus muncul.  Cerita menonjolkan perjuangan Hideki sebagai manusia biasa yang ditempatkan dalam posisi besar, pembangunan karakter tim MAT, serta hadirnya dua Ultraman senior—Ultraman pertama dan Ultraseven—yang sesekali turun membantu ketika ancaman sangat berat. Pada akhirnya, Ultraman Jack berperan sebagai pelindung utama bumi pada masa itu.', '', 'https://images.static-bluray.com/movies/covers/284717_front.jpg', NULL),
(140, 'Ultraman X', 'ultraman-x', 'Ultraman X mengambil latar ketika fenomena kosmis bernama Ultra Flare meledak di seluruh tata surya. Ledakan ini membangkitkan kembali monster-monster yang sebelumnya membatu. Untuk menghadapi ancaman tersebut, dibentuklah organisasi pertahanan khusus bernama Xio.  Tokoh utama, Daichi Ozora, adalah anggota muda Xio yang memiliki rasa ingin tahu besar tentang makhluk raksasa. Suatu hari, ia terhubung dengan makhluk cahaya misterius bernama Ultraman X, setelah Daichi memakai perangkat khusus bernama X Devizer. Sejak saat itu, Daichi dapat berubah menjadi Ultraman X.  Ultraman X memiliki ciri unik: ia dapat menggunakan Cyber Cards, kartu data berisi kekuatan Ultraman atau monster tertentu. Dengan memindai kartu tersebut, X bisa mengaktifkan armor dan kemampuan khusus seperti Zana Armor, Eleking Armor, atau Beta Capsule Armor.  Sepanjang cerita, Daichi dan Ultraman X bekerja sama menangani kebangkitan monster, mengungkap misteri Ultra Flare, hingga menghadapi alien yang mencoba memanfaatkan kekacauan tersebut. Hubungan Daichi dan X juga menjadi fokus utama, karena mereka belajar memahami pandangan satu sama lain—manusia dan makhluk cahaya—terhadap perlindungan bumi.', '', 'https://images-na.ssl-images-amazon.com/images/S/pv-target-images/8c5289fdafab110c8c251d1da1d9dfbf23a78b9dbb49686b46adb2d56f41e232._RI_V_TTW_.jpg', NULL),
(141, 'Ultraman R&B (Ultraman Rube)', 'ultraman-rb-ultraman-rube', 'Ultraman R/B menceritakan dua bersaudara, Katsumi Minato dan Isami Minato, yang hidup di kota Ayaka. Suatu hari, kota mereka kembali diserang monster setelah bertahun-tahun damai. Dalam situasi genting itu, mereka menemukan R/B Gyro dan R/B Crystal, artefak misterius yang memungkinkan mereka berubah menjadi Ultraman.  Katsumi menjadi Ultraman Rosso, sementara Isami menjadi Ultraman Blu. Keduanya berjuang melindungi kota dari ancaman monster yang terus muncul, sambil mencari tahu hubungan antara kekuatan Ultraman dengan kejadian hilangnya ibu mereka beberapa tahun lalu.  Sepanjang cerita, hubungan kakak-adik ini diuji melalui konflik, perbedaan sifat, dan tekanan sebagai pahlawan baru. Mereka juga bertemu lawan kuat serta mengungkap misteri di balik kekuatan elemen api dan air yang mereka gunakan. Cerita berkembang hingga keduanya dapat bersatu sebagai bentuk gabungan Ultraman R/B (Ruebe), menandai semakin eratnya kerja sama mereka.', '', 'https://br.web.img3.acsta.net/pictures/22/09/13/18/54/4484521.jpg', NULL),
(142, 'Kamen Rider Ghost', 'kamen-rider-ghost', 'Kamen Rider Ghost menceritakan Takeru Tenkuji, seorang pemuda yang bercita-cita menjadi seorang Ghost Hunter seperti ayahnya. Pada usia 18 tahun, ia tewas saat melindungi seorang gadis dari serangan makhluk misterius bernama Gamma. Namun, ia dihidupkan kembali oleh sebuah entitas bernama Eyecon dan mendapat kesempatan kedua untuk hidup selama 99 hari.  Selama waktu itu, Takeru harus mengumpulkan 15 Heroic Eyecons, yaitu jiwa para tokoh besar seperti Musashi, Robin Hood, Edison, Newton, hingga Beethoven. Jika semua Eyecon terkumpul sebelum batas waktu, ia dapat hidup kembali secara permanen. Dengan kekuatan tersebut, Takeru berubah menjadi Kamen Rider Ghost, bertarung melawan para Gamma yang berasal dari dimensi lain.  Perjalanan Takeru tidak sekadar mengumpulkan Eyecon. Ia juga mengungkap misteri kematian ayahnya, asal-usul dunia Gamma, dan hubungan antara manusia dengan jiwa mereka. Konflik semakin besar ketika terungkap bahwa dunia Gamma dipimpin oleh Adel dan keluarganya, yang memiliki rencana untuk menyatukan dunia manusia dengan dunia Gamma secara destruktif.  Akhir cerita menggambarkan Takeru berhasil mengumpulkan semua Eyecon, menyelamatkan kedua dunia, serta memperoleh kembali kehidupannya sebagai manusia. Ia tetap menjaga hubungan dengan para roh pahlawan dan melanjutkan hidup sambil memahami arti keberadaan serta pentingnya hubungan antar manusia.', '', 'https://media.fstatic.com/iG8vmfEckqjuTErTQwWW0nhZdpo=/322x478/smart/filters:format(webp)/media/movies/covers/2016/01/kamen-rider-ghost_t192094.jpg', NULL),
(143, 'Kamen Rider Fourze', 'kamen-rider-fourze', 'Kamen Rider Fourze mengikuti kisah Kisaragi Gentaro, siswa baru di Amanogawa High School yang memiliki tekad sederhana: berteman dengan semua orang di sekolahnya. Gentaro bergabung dengan Kamen Rider Club, kelompok kecil yang menyelidiki fenomena aneh yang terjadi di sekolah, terutama kemunculan monster bernama Zodiarts.  Zodiarts berasal dari Zodiarts Switch, perangkat yang dapat mengubah manusia menjadi monster berdasarkan rasi bintang. Switch ini disebarkan secara diam-diam oleh organisasi misterius Horoscope, kelompok Zodiarts tingkat tinggi yang memiliki kekuatan jauh lebih besar. Mereka berusaha bereksperimen pada para siswa dan memicu evolusi Zodiarts ke tingkat yang lebih kuat.  Dengan bantuan teman-temannya—Yuki, Kengo, Miu, JK, Shun, dan Tomoko—Gentaro menggunakan Fourze Driver dan berbagai Astro Switch untuk berubah menjadi Kamen Rider Fourze, Rider dengan kekuatan berbasis luar angkasa, roket, dan modul-modul teknologi unik.  Seiring berkembangnya cerita, terungkap bahwa proyek Zodiarts berkaitan dengan penelitian luar angkasa, tragedi masa lalu, dan ambisi besar para Horoscope untuk melampaui batas manusia. Gentaro menghadapi mereka sambil memegang teguh prinsipnya: bahwa bahkan orang yang tersesat pun bisa diselamatkan melalui persahabatan.  Di akhir cerita, Gentaro berhasil menghentikan para Horoscope, mengakhiri proyek Zodiarts, dan menyatukan kembali sekolah yang sebelumnya diliputi konflik. Semangat persahabatannya menjadi kunci kemenangan dan fondasi baru bagi masa depan Amanogawa High School.', '', 'https://iv1.lisimg.com/image/7004388/740full-kamen-rider-fourze-poster.jpg', NULL),
(144, 'Paddle Pop Max Adventures', 'paddle-pop-max-adventures', 'Paddle Pop mengikuti petualangan Paddle Pop Lion (Max), pewaris sah Kerajaan Singa. Ia harus melarikan diri sejak kecil karena kerajaannya dihancurkan oleh penyihir jahat Shadow Master, yang menginginkan kekuatan kuno bernama Lion Kingdom’s Elemental Powers.  Dalam perjalanannya, Max tumbuh sebagai pemuda pemberani dan mulai mengumpulkan berbagai Batu Elemen (seperti Es, Api, Angin, dan Petir) yang menyimpan kekuatan luar biasa. Ia ditemani sahabat-sahabatnya, seperti Leena, Kara, dan makhluk-makhluk dari berbagai ras. Mereka menghadapi tantangan, monster, perangkap, dan pasukan Shadow Master yang ingin mencegah Max mendapatkan semua elemen.  Setiap musim menampilkan petualangan berbeda: pencarian Batu Es, pertarungan di dunia kuno, eksplorasi pulau misterius, hingga perjalanan waktu. Namun semuanya bermuara pada satu tujuan: menghentikan Shadow Master yang berusaha menguasai seluruh elemen untuk menguasai dunia.  Pada akhirnya, Max menemukan kebenaran tentang masa lalunya, memulihkan kembali kehormatan Kerajaan Singa, serta mengalahkan Shadow Master dengan kekuatan keberanian dan persahabatan. Dunia kembali damai, dan Max menjadi simbol harapan bagi semua makhluk.', '', 'https://www.static-src.com/wcsstore/Indraprastha/images/catalog/full/99/MTA-40290784/brd-44261_original-activity-book-petualangan-paddle-pop-dinoterra-oleh-tim-pe-buku-aktivitas_full01.jpg', NULL),
(145, 'Kamen Rider OOO', 'kamen-rider-ooo', 'Kamen Rider OOO berpusat pada Eiji Hino, seorang pemuda sederhana yang tidak punya ambisi dan hidup berpindah-pindah. Ia kemudian bertemu dengan Ankh, salah satu dari para Greeed, makhluk homunkulus yang terbuat dari Koin Core dan terbangun setelah tidur selama 800 tahun. Para Greeed bangkit karena hasrat manusia, dan mereka menciptakan monster bernama Yummy untuk memenuhi keinginan tersebut.  Ankh, yang kehilangan sebagian besar tubuh aslinya, bekerja sama dengan Eiji. Ia memberikan OOO Driver dan Core Medals yang memungkinkan Eiji berubah menjadi Kamen Rider OOO. Dengan kombinasi tiga medal dari jenis Hewan Buruan (Burung, Kucing Besar, Serangga, dll.), Eiji memiliki berbagai bentuk seperti Taka–Tora–Batta hingga combo penuh seperti Tajador, Gatakiriba, dan Latorartar.  Konflik utama berkisar pada perebutan Core Medals antar Greeed, ambisi mereka untuk menjadi sempurna, dan keterlibatan organisasi misterius Kougami Foundation yang mendorong lahirnya berbagai eksperimen demi “kebangkitan ulang” manusia. Di sisi lain, Eiji harus menjaga agar kekuatan OOO tidak membuatnya kehilangan kemanusiaannya, karena penggunaan medal tertentu dapat memicu insting liar.  Cerita mencapai puncak ketika rahasia masa lalu Ankh terbongkar, hubungan kemitraannya dengan Eiji berkembang menjadi saling percaya, dan para Greeed berusaha mencapai bentuk sempurna yang mengancam dunia. Pada akhir cerita, Eiji berhasil menghentikan rencana Greeed, namun pengorbanan besar dilakukan, khususnya terkait nasib Ankh. Meskipun penuh kepedihan, Eiji tetap berpegang pada keyakinannya untuk menolong siapa pun tanpa pamrih.', '', 'https://artworks.thetvdb.com/banners/posters/5d82f4b56f9b0.jpg', NULL),
(146, 'Kamen Rider Zero-One', 'kamen-rider-zero-one', 'Kamen Rider Zero-One berlatar di masa ketika robot humanoid bernama HumaGear telah menjadi bagian dari kehidupan manusia. Mereka membantu di banyak bidang: pelayanan publik, hiburan, pendidikan, dan pekerjaan industri. Namun keberadaan mereka mulai terancam ketika organisasi teroris siber MetsubouJinrai.net meretas HumaGear dan mengubahnya menjadi monster bernama Magia.  Tokoh utama, Aruto Hiden, seorang komedian gagal, tiba-tiba menjadi presiden baru Hiden Intelligence setelah kakeknya, pemilik perusahaan, wafat. Ia menerima tanggung jawab besar ini dan memakai Zero-One Driver untuk berubah menjadi Kamen Rider Zero-One, demi menghentikan teror terhadap HumaGear dan membuktikan bahwa manusia dan robot dapat hidup berdampingan.  Di sisi lain, badan pemerintah A.I.M.S. awalnya menganggap HumaGear sebagai ancaman. Dua anggotanya, Isamu Fuwa (Kamen Rider Vulcan) dan Yua Yaiba (Kamen Rider Valkyrie), bekerja di garis depan menghadapi serangan Magia, meski memiliki agenda berbeda.  Konflik memuncak dengan munculnya sosok misterius Gai Amatsu, pemilik ZAIA Enterprise, yang ingin mengambil alih Hiden Intelligence dan membuktikan bahwa kecerdasan buatan harus berada di bawah kendalinya. Persaingan bisnis berubah menjadi pertarungan ideologi, teknologi, dan kendali atas masa depan.  Seiring cerita berjalan, Aruto menghadapi dilema moral tentang batas antara manusia dan AI, terutama setelah tragedi yang menimpa HumaGear yang dekat dengannya. Ia kemudian menciptakan kekuatan baru Zero-Two untuk melawan ancaman yang semakin besar, termasuk kebangkitan kembali MetsubouJinrai.net yang memiliki rencana global.', '', 'https://news.tokunation.com/wp-content/uploads/sites/5/2022/08/Kamen_Rider_Zero_One__01_Photo.jpg', NULL),
(147, 'Tate no Yuusha no Nariagari (The Rising of the Shield Hero)', 'tate-no-yuusha-no-nariagari-the-rising-of-the-shield-hero', 'Naofumi Iwatani, seorang mahasiswa biasa, tiba-tiba dipanggil ke dunia lain bersama tiga orang lain sebagai Empat Pahlawan Legendaris: Pahlawan Pedang, Tombak, Busur, dan Perisai. Naofumi mendapat peran sebagai Pahlawan Perisai, satu-satunya yang tidak bisa menyerang secara langsung, sehingga dianggap paling lemah.  Berbeda dari yang lain, Naofumi justru dikhianati sejak hari pertama. Ia difitnah melakukan kejahatan yang tidak pernah ia lakukan, membuat reputasinya hancur dan membuat seluruh kerajaan memusuhinya. Dipenuhi rasa kecewa dan kemarahan, Naofumi memilih bertarung sendirian, mengandalkan kekuatan bertahan dan kemampuan mendukung yang terus berkembang.  Perjalanannya berubah ketika ia membeli seorang demi-human bernama Raphtalia sebagai partner. Hubungan mereka berkembang dari transaksi paksa menjadi kemitraan penuh kepercayaan. Bersama Raphtalia, kemudian juga Filo dan rekan-rekan lain, Naofumi mulai mendapatkan kekuatan baru untuk menghadapi ancaman besar bernama Waves, gelombang monster yang mengancam seluruh dunia.  Konflik semakin luas ketika rahasia tentang dunia lain, para Pahlawan lain, dan tujuan sebenarnya dari Waves terungkap. Naofumi, yang awalnya dibenci, perlahan menjadi pilar utama dalam melindungi dunia, menghadapi politik kerajaan, pengkhianatan, bahkan Pahlawan lain yang sering bertindak ceroboh.  Pada akhirnya, perjalanan Naofumi adalah kisah bangkitnya seseorang dari kehinaan menuju penghormatan, membuktikan bahwa kekuatan sejati tidak selalu datang dari serangan, tetapi dari keteguhan hati dan kemampuan melindungi siapa pun yang mempercayainya.', '', 'https://www.baka-tsuki.org/project/images/b/b3/Tate_no_Yuusha_no_Nariagari_Volume_6_Cover.jpg', NULL),
(148, 'Mahabarata', 'mahabarata', 'Mahabarata adalah epos besar India kuno yang menceritakan konflik antara dua kelompok keluarga keturunan Raja Kuru: Pandawa dan Kurawa. Inti ceritanya berfokus pada perebutan kekuasaan atas Kerajaan Hastinapura, yang berakhir pada perang besar bernama Kurukshetra.  Pandawa terdiri dari lima bersaudara: Yudhistira, Bima, Arjuna, serta si kembar Nakula dan Sahadeva. Mereka adalah putra Pandu, raja yang adil. Sementara Kurawa adalah 100 putra Raja Dretarastra yang dipimpin oleh Duryodana, yang iri terhadap kedudukan dan popularitas Pandawa.  Ketegangan memuncak ketika Duryodana menipu Yudhistira melalui permainan dadu yang membuat Pandawa kehilangan kerajaan dan harus hidup dalam pembuangan selama 13 tahun. Setelah masa pengasingan berakhir, Pandawa menuntut hak mereka kembali, namun Kurawa menolak. Perang pun tak terelakkan.  Dalam perang Kurukshetra, berbagai kerajaan ikut bergabung di kedua pihak. Kisah ini juga memuat ajaran penting melalui dialog Arjuna dan Kresna dalam Bhagavad Gita, yang membahas kewajiban, moralitas, dan makna dharma.  Peperangan berlangsung sengit selama 18 hari. Banyak pahlawan besar gugur, termasuk Bhisma, Karna, dan Drona. Akhirnya Pandawa memenangkan perang, dan Yudhistira naik takhta sebagai raja Hastinapura, meski kemenangan itu membawa duka karena banyak saudara dan guru yang tewas.  Mahabarata bukan hanya kisah perang, tetapi juga mengangkat tema tentang keadilan, kesetiaan, pengkhianatan, dan perjalanan spiritual manusia dalam menghadapi takdir.', '', 'https://pictures.abebooks.com/isbn/9788175082731-us.jpg', NULL),
(149, 'Karna', 'karna', 'Karna adalah salah satu tokoh paling tragis dan kompleks dalam Mahabarata. Ia sebenarnya putra Kunti dan dewa matahari Surya, lahir sebelum Kunti menikah. Karena takut aib, Kunti melepaskannya di sungai dalam sebuah keranjang. Karna ditemukan dan dibesarkan oleh pasangan kusir, membuatnya tumbuh sebagai bangsawan yang tidak diakui.  Sejak muda, Karna memiliki bakat luar biasa dalam ilmu perang, terutama memanah. Namun, karena status kelahirannya dianggap rendah, ia sering diremehkan. Ketika ia menantang Arjuna dalam sebuah kontes, Karna dihina karena bukan kesatria. Duryodana, pangeran Kurawa, kemudian mengangkat Karna menjadi raja Anga, sehingga Karna mendapatkan kehormatan sebagai kesatria. Sejak itu, Karna berjanji setia kepada Duryodana.  Karna terkenal karena kemurahan hati dan rasa setia kawan yang tak tergoyahkan. Namun, kesetiaannya pada Duryodana membuatnya berseberangan dengan Pandawa, padahal ia sebenarnya saudara kandung mereka. Saat perang Kurukshetra mendekat, Kunti mengungkapkan jati dirinya, tetapi Karna menolak mengkhianati Duryodana, meskipun tahu ia akan menghadapi kematian.  Dalam perang, Karna menjadi salah satu prajurit utama Kurawa dan hampir mengalahkan Arjuna. Namun nasib buruk dan kutukan masa lalunya—dari seorang brahmana dan dari ibu angkatnya—menghalangi kekuatannya di saat-saat penting. Pada hari ke-17, saat keretanya terjebak di tanah, Karna tidak mampu menggunakan ilmu-ilmu pamungkasnya. Arjuna, atas perintah Kresna, akhirnya membunuh Karna dalam kondisi bertahan.  Kematian Karna mengungkapkan kebenaran pahit: ia adalah putra tertua Kunti dan pewaris sah keluarga Pandawa. Tragedi hidupnya menggambarkan konflik antara kehormatan, takdir, dan kesetiaan, menjadikannya salah satu tokoh paling dihormati dan paling menyedihkan dalam Mahabarata.', '', 'https://www.isvara.org/archive/wp-content/uploads/karna.jpg', NULL),
(150, 'Little Krishna', 'little-krishna', 'Little Krishna adalah serial animasi yang menceritakan masa kecil Dewa Krishna di desa Vrindavan. Cerita berfokus pada petualangan Krishna kecil, yang dikenal sebagai anak nakal, ceria, dan penuh keajaiban. Ia tinggal bersama keluarga angkatnya, Nanda dan Yashoda, serta sahabat-sahabatnya seperti Balarama dan para Gopi.  Di balik kehidupannya yang tampak sederhana, Little Krishna memiliki tugas ilahi: melindungi penduduk Vrindavan dari berbagai ancaman, terutama dari Raja Kamsa, penguasa jahat dari Mathura yang mengetahui bahwa seorang anak yang kelak akan menjatuhkannya telah lahir di Vrindavan. Karena itu, Kamsa terus mengirim para monster dan iblis untuk membunuh Krishna.  Setiap episode menampilkan berbagai aksi heroik Krishna, seperti menaklukkan ular raksasa Kaliya, menggagalkan serangan iblis Putana, Trinavarta, dan makhluk-makhluk lain, sekaligus menampilkan perilaku jahilnya yang mencuri mentega dan membuat para Gopi kewalahan.  Meski penuh aksi, seri ini juga menekankan nilai moral seperti keberanian, kesetiaan, cinta keluarga, dan kebaikan hati. Little Krishna tumbuh bukan hanya sebagai penyelamat Vrindavan, tetapi juga sebagai anak yang dicintai semua orang karena sifatnya yang hangat dan penuh kasih.', '', 'https://m.media-amazon.com/images/S/pv-target-images/5c2f177a50d038f382e8748f4bcc9a8ae8ccdc530374272ce00428eadbc2d190.jpg', NULL),
(151, 'Kamen Rider Ryuki', 'kamen-rider-ryuki', 'Kamen Rider Ryuki berfokus pada Shinji Kido, seorang jurnalis muda dari situs berita ORE Journal. Saat menyelidiki kasus orang hilang, ia menemukan dunia paralel bernama Mirror World, tempat monster Mirror Monster memangsa manusia. Di sana, Shinji bertemu Kamen Rider Knight (Ren Akiyama) dan kemudian mendapatkan kontrak dengan naga Mirror Monster bernama Dragreder, yang memungkinkannya berubah menjadi Kamen Rider Ryuki.  Namun, Shinji segera mengetahui kenyataan pahit: para Rider bukan sekadar pahlawan. Mereka terlibat dalam Rider War, pertarungan mematikan yang diatur oleh seorang bernama Shiro Kanzaki. Para Rider dipaksa bertarung sampai hanya satu yang tersisa, dan pemenangnya akan mendapatkan satu permintaan apa pun. Setiap Rider memiliki motivasi pribadi, trauma, atau tujuan egois yang membuat perang ini semakin brutal.  Shinji, yang tidak setuju dengan peperangan ini, berusaha menghentikan konflik dan menyelamatkan semua orang, meskipun ia sendiri adalah salah satu peserta. Ia mencoba menolong para Rider dan korban Mirror Monsters, tapi niat baiknya sering bertabrakan dengan ambisi dan keputusasaan Rider lain seperti Asakura, Kitaoka, Toujou, dan bahkan Ren sendiri yang memiliki misi menyelamatkan orang yang ia cintai.  Seiring waktu, terungkap bahwa Rider War dimulai sebagai cara bagi Shiro Kanzaki untuk menyelamatkan adiknya, Yui, yang nasibnya terkait erat dengan Mirror World. Konflik berujung pada pengorbanan dan kehancuran besar, namun terakhir, waktu diputar ulang sehingga Rider War dibatalkan sebelum dimulai. Dunia kembali seperti semula, meski beberapa kenangan dan perasaan para tokohnya tetap menjadi jejak yang tidak terlihat.  Kamen Rider Ryuki dipandang sebagai salah satu seri paling gelap dan tragis dalam franchise, karena menekankan konflik moral, pilihan hidup, dan konsekuensi dari keinginan manusia.', '', 'https://images.static-bluray.com/movies/covers/328292_front.jpg', NULL),
(152, 'Fate stay night', 'fate-stay-night', 'konflik besar bernama Perang Cawan Suci, sebuah pertarungan rahasia yang terjadi di kota Fuyuki. Tujuh penyihir (Master) memanggil tujuh roh pahlawan legendaris (Servant) untuk bertarung hingga tersisa satu pasangan. Pemenangnya akan mendapatkan Cawan Suci, artefak yang mampu mengabulkan satu permintaan apa pun.  Tokoh utama, Shirou Emiya, seorang remaja baik hati yang selamat dari tragedi kebakaran besar beberapa tahun lalu, tanpa sengaja terlibat dalam perang ini. Ia memanggil seorang Servant perempuan berarmor, yaitu Saber, yang ternyata adalah roh dari raja besar masa lalu. Shirou yang tidak berpengalaman terpaksa berjuang demi bertahan hidup, tetapi juga demi melindungi orang lain.  Konflik semakin rumit dengan kemunculan Master dan Servant lain seperti Rin Tohsaka dengan Archer, Illya dengan Berserker, serta berbagai pihak yang punya ambisi masing-masing. Shirou perlahan mengungkap kebenaran kelam di balik Perang Cawan Suci, termasuk kenyataan bahwa Cawan Suci tidak sesuci yang dibayangkan.  Setiap rute cerita diadaptasi dalam versi anime yang berbeda:  Fate Route: fokus pada Shirou dan Saber, dengan tema idealisme dan pengorbanan.  Unlimited Blade Works: berfokus pada konflik ideal Shirou dan Archer.  Heaven’s Feel: lebih gelap, tentang rahasia Cawan Suci dan kisah mendalam Sakura Matou.  Secara keseluruhan, Fate/stay night menggambarkan pertempuran antara idealisme, takdir, dan pilihan moral, sekaligus menampilkan pertarungan epik para pahlawan legendaris dari berbagai era.', '', 'https://image.tmdb.org/t/p/original/rSVf1sgz1UGlzITEPANRtFdBbXY.jpg', NULL),
(153, 'Squid Game', 'squid-game', 'Squid Game menceritakan sekelompok orang yang terlilit masalah ekonomi berat dan menerima undangan misterius untuk mengikuti serangkaian permainan anak-anak tradisional Korea. Mereka dijanjikan hadiah uang dalam jumlah sangat besar jika berhasil menyelesaikan semua permainan. Namun begitu permainan dimulai, mereka segera menyadari bahwa setiap kekalahan berarti kematian.  Tokoh utama, Seong Gi-hun, seorang pria yang terjerat hutang dan kesulitan hidup, memutuskan ikut demi memperbaiki nasibnya dan membantu keluarganya. Ia dan ratusan peserta lain dikurung di sebuah fasilitas rahasia dan diawasi oleh penjaga berseragam merah serta seorang pemimpin bertopeng hitam yang disebut Front Man.  Permainan demi permainan menguji insting bertahan hidup, kepercayaan, dan moralitas setiap peserta: mulai dari permainan tradisional seperti Lampu Merah Lampu Hijau, tarik tambang, hingga permainan yang menuntut pengorbanan dan pengkhianatan. Di balik layar, terdapat kelompok elit yang menjadikan permainan tersebut sebagai hiburan gelap.  Saat jumlah peserta terus berkurang, Gi-hun berjuang mempertahankan nilai kemanusiaannya, bahkan ketika ia harus membuat keputusan-keputusan sulit. Pada akhirnya, rahasia tentang penyelenggara permainan terungkap, termasuk twist mengejutkan mengenai sosok yang tampaknya tidak berbahaya.  Squid Game mengangkat tema kesenjangan sosial, ketamakan, dan bagaimana manusia berubah ketika hidup dipertaruhkan dalam sistem yang kejam.', '', 'https://d24jnm9llkb1ub.cloudfront.net/icpn/00602445448128/00602445448128-cover-zoom.jpg', NULL),
(154, 'Armor Hero', 'armor-hero', 'Dunia Armor Hero bercerita tentang sekelompok anak muda yang terpilih untuk menjadi Armor Hero, para ksatria berzirah yang mendapat kekuatan dari Armor Spirit, roh kuno pelindung umat manusia. Tugas mereka adalah melawan Dark Force, kekuatan kegelapan yang ingin mengambil alih dunia dengan membangkitkan monster-monster kuno.  Para Armor Hero harus belajar bekerja sama, mengendalikan kekuatan mereka, dan menghadapi ancaman yang semakin kuat. Konflik antar karakter, misteri asal kekuatan Armor, dan hubungan antar generasi pahlawan menjadi inti cerita.', '', 'https://4.bp.blogspot.com/-OmN7NouWcW0/TY_9iRqJI8I/AAAAAAAAAkk/_kdbJdgFoE0/s1600/HeadRightArmorHero.jpg', NULL),
(155, 'Finding Nemo', 'finding-nemo', 'Finding Nemo menceritakan perjalanan seekor ikan badut bernama Marlin yang sangat protektif terhadap anaknya, Nemo, setelah kehilangan istri dan telur-telurnya akibat serangan barracuda. Suatu hari, Nemo yang mulai merasa dibatasi oleh ayahnya nekat berenang terlalu jauh ke luar terumbu karang dan tertangkap oleh seorang penyelam. Ia kemudian dibawa ke sebuah akuarium di klinik dokter gigi di Sydney.  Marlin yang panik memulai perjalanan panjang melintasi lautan untuk menyelamatkan Nemo. Dalam perjalanan, ia ditemani oleh Dory, ikan biru yang ramah namun memiliki masalah ingatan jangka pendek. Keduanya menghadapi berbagai rintangan, seperti kawanan hiu, ubur-ubur beracun, dan penyu laut.  Sementara itu, Nemo mencoba mencari cara melarikan diri dari akuarium bersama ikan-ikan lain di sana. Dengan keberanian dan kecerdikan, ia hampir berhasil sebelum akhirnya Marlin dan Dory tiba di Sydney. Setelah serangkaian kejadian dramatis, ayah dan anak itu akhirnya bersatu kembali.', '', 'https://images.wehkamp.nl/i/wehkamp/369762_pb_01/finding-nemo-dvd-8717418394578.jpg', NULL),
(156, 'Hataraku Maou-sama!', 'hataraku-maou-sama', 'Hataraku Maou-sama! mengisahkan raja iblis bernama Satan Jacob dari dunia Ente Isla. Saat hampir dikalahkan oleh pahlawan Emilia, ia melarikan diri melalui portal antar-dimensi. Namun, ia justru tiba di dunia manusia, tepatnya di Tokyo, dan kehilangan hampir seluruh kekuatannya. Karena tidak bisa kembali dan harus bertahan hidup, Satan mengambil nama Sadao Maou dan bekerja paruh waktu di restoran cepat saji MgRonalds.  Sambil menyesuaikan diri dengan kehidupan sehari-hari, Maou berusaha memahami dunia modern: membayar sewa kos, menghemat uang, dan menjadi karyawan teladan. Kehidupan barunya semakin rumit ketika Emilia, yang juga terlempar ke dunia manusia dan memakai nama Emi Yusa, muncul untuk mengawasinya. Alih-alih perang besar, mereka justru terlibat dalam masalah-masalah kecil sehari-hari yang kocak, sambil menghadapi ancaman baru dari Ente Isla yang ikut datang ke dunia manusia.  Cerita ini memadukan komedi, fantasi, dan slice-of-life, menunjukkan bagaimana seorang raja iblis legendaris berjuang bukan untuk menaklukkan dunia, tetapi untuk mendapat gaji dan promosi kerja.', '', 'https://freshcomics.s3.amazonaws.com/cache/2e/a1/2ea1a444224730eab86d554776b2deed.jpg', NULL),
(157, 'Mahaputra', 'mahaputra', 'Mahaputra adalah serial sejarah–drama India yang mengisahkan kehidupan Maharana Pratap, pahlawan legendaris dari kerajaan Mewar. Cerita berfokus pada perjalanan Pratap sejak masa kecilnya sebagai putra Raja Udai Singh hingga menjadi seorang kesatria besar yang dikenal karena keberanian, prinsip, dan pengabdian pada tanah kelahirannya.  Sejak kecil, Pratap menunjukkan sifat jujur, adil, dan gagah berani. Ia dibesarkan di tengah intrik kerajaan, terutama persaingannya dengan saudara tirinya, Jagmal, serta ketegangan politik yang melibatkan ibu tirinya, Rani Dheer Bai. Mewar terus menghadapi ancaman dari Kekaisaran Mughal yang dipimpin Kaisar Akbar, sehingga Pratap harus tumbuh cepat menjadi pemimpin yang kuat.  Saat dewasa, Pratap dikenal sebagai kesatria yang teguh mempertahankan kehormatan dan kedaulatan Mewar. Ia menjalin hubungan mendalam dengan Maharani Ajabde, yang selalu menjadi penopang moralnya. Konflik utama dalam cerita memuncak pada Pertempuran Haldighati, di mana Pratap melawan pasukan Mughal dengan keberanian luar biasa, meski harus menghadapi kekuatan musuh yang jauh lebih besar.  Serial ini menonjolkan nilai kehormatan, strategi perang, cinta tanah air, dan pengorbanan seorang pemimpin yang memilih mempertahankan prinsip daripada tunduk pada kekuasaan besar. Cerita berakhir dengan penggambaran Pratap sebagai simbol semangat perjuangan rakyat Mewar dan salah satu figur paling dihormati dalam sejarah Rajput.', '', 'https://1.bp.blogspot.com/-RyI06RyVimA/VoGEuvM63kI/AAAAAAAACYk/nMHFkC51onA/s1600/2015-12-29_01.51.00.jpg', NULL),
(158, 'Haikyuu!!', 'haikyuu', 'Haikyuu!! menceritakan perjalanan Shoyo Hinata, seorang siswa bertubuh pendek yang bercita-cita menjadi pemain voli hebat setelah terinspirasi oleh legenda Little Giant. Meskipun kekurangan tinggi badan, Hinata memiliki tekad kuat, kecepatan luar biasa, dan semangat pantang menyerah.  Saat masuk SMA Karasuno, Hinata berharap bisa memulai karier volinya. Namun, ia mendapati bahwa ia harus bermain satu tim dengan rival masa SMP-nya, setter jenius namun keras kepala, Tobio Kageyama. Awalnya mereka sering bertengkar, tapi perlahan keduanya menyadari bahwa mereka bisa menjadi duo yang sangat kuat: spiker cepat dan setter presisi.  Bersama rekan satu tim Karasuno—termasuk Daichi, Suga, Asahi, Nishinoya, Tanaka, Tsukishima, Yamaguchi, dan pelatih Ukai—mereka berlatih keras untuk mengembalikan kejayaan Karasuno yang dulu dijuluki Burung Gagak yang Tak Bisa Terbang.  Perjalanan mereka penuh pertandingan menegangkan, rivalitas sengit dengan sekolah seperti Nekoma, Aoba Johsai, dan Shiratorizawa, serta momen-momen emosional yang menggambarkan pertumbuhan pribadi dan kekuatan kerja sama tim.', '', 'https://upload.wikimedia.org/wikipedia/id/6/6b/Haiky%C5%AB_Volume_1.jpg', NULL);
